// Purdex mod — self relay (spec §8.1–§8.3 steps 4–8, §8.7).
//
//   idle ──(turn.complete: used ≥ threshold, growth ≥ minGrowth, +10 since last ask)──▶ beginning
//   beginning: `pdx relay begin --self` runs from a timer ──▶ awaiting, or back to idle on a refusal
//   awaiting: a timer loops `pdx relay wait` and alone asks the daemon and moves the state;
//   every prompt.submit is held until that loop's answer (≤ 11 min), on local `/bin/sleep 5`
//   calls of its own (P5b-3 critic), and one that arrives while beginning waits for begin's
//   answer first (≤ 40 s); every prompt is held, however many (U7: no new turn while a request is open)
//   awaiting ──approved──▶ approved: write prompt submitted (a fresh nonce), report writing
//   approved ──(turn.complete of the write turn, file ok)──▶ clearing: report written, timer → /clear
//   clearing ──(classic.SessionStart source=clear)──▶ seeding: report cleared --new-session, hello, seed prompt
//   seeding ──(turn.complete of the seed turn)──▶ idle: report done, floor = tokens now
//
// A member never begins: at the same gate it asks its lead (`pdx relay ask`, maybeAsk) and keeps working; the lead's
// `pdx relay _<ref>` arrives as the control message of the member relay (protocol 3, member relay ask spec §4).
//   awaiting ──denied / timeout / cancelled / unavailable──▶ idle (ask again at +10 points)
//   a deferred step that fails (prompt refused, /clear refused) ──▶ idle: write / fix / seed report
//   failed{handoff_incomplete}, /clear reports cancelled{abandoned}
//   the user's own /clear ──▶ idle: awaiting / approved report cancelled{abandoned}, seeding
//   failed{handoff_incomplete}; a begin still out is cancelled{abandoned} when it answers (s.gen)
//   a compaction ──▶ awaiting reports cancelled{compacted}, idle; approved skips an auto one
//   every return to idle lets the request go first (letGo): its held prompts go on at once,
//   unchanged, before any report; the loop's late answer for it is ignored
//
// Idle relay (docs/specs/2026-10-11-idle-relay-spec-plan.md §4): when hello advertised idle_minutes, an ordinary session
// idle that long at ≥ idle_threshold % asks for a relay the same way (begin --reason idle). That ask never holds a
// prompt (D6): one that arrives while it is open withdraws it (cancelled{resumed}) and goes on unchanged.
//
// Everything that starts a turn, runs a command or waits on the daemon goes
// out from a $.clock.after timer, never inside a hook: $.command.run rejects
// inside a hook the turn waits on (F3), and a daemon that is down answers
// only after the client's 30 s grace, which no turn end, session start or
// /clear may wait for (P5b-1 review). Hooks only read the engine and move
// the state. Two hooks wait on purpose: the prompt hold, on local
// `/bin/sleep 5` calls (a `$` call in flight stops the hook's 10 s budget,
// HookBudget; it asks the daemon nothing, the timers ask it and move the
// state) and failing open; and /relay, on its daemon call (the person waits
// for its output; 8 s bound).
//
// Each write / fix / seed prompt is composed at use (U21, spec §8.8): the
// mod's own fixed head and tail (prompts.js) around the body that `pdx relay
// prompts` answers right before the prompt goes out, from the step's timer
// (8 s bound); a call that fails, times out or answers junk gives the
// built-in body, and the relay goes on.
//
// This file is the plugin's one hooks module (hooks/hooks.json names a single
// path); it also registers ask.js, the AskUserQuestion 分流 (P8a-2), and
// events.js, the event reporter (interface U1 spec §6.5), and imports
// prompts.js, the copy of the daemon's relay prompts generated from
// internal/team/relay_prompts.go (P9a): the fixed head and tail of each
// prompt, and the built-in bodies.

import { register as registerAsk } from './ask.js'
import { backgroundBusy, registerEvents } from './events.js'
import { registerGate } from './gate.js'
import { CONSUMED, CONSUMED_REASK, claimOp, controlOp, controlReask, leadLine, parseTeamArgs, parseTeamNames, rosterLines } from './member.js'
import { DEFAULT_BODIES, FIXED } from './prompts.js'

const VERSION = '9' // the mod ↔ daemon protocol version `pdx relay hello --version` reports (5: the paused latch and the reask control; 6: person tokens, /team and the direct /relay; 7: the ask ladder - lastAskPct only on an answer, no ask past 90 %, an unanswered final card; 8: the idle half - an idle card's timeout writes the handoff file without clearing, and a later relay reuses it; 9: a member's idle compaction is intercepted and its lead told)
const DEFAULT_THRESHOLD = 70
const DEFAULT_MIN_GROWTH = 20000
const REASK_POINTS = 10
const UNANSWERED_RETRY_MS = 30_000 // an unanswered card whose poll failed is polled again after this
const LAST_ASK_PCT = 90 // from here an ask is the last one (relay/team rules v2 §4.2): the daemon pauses the session when it goes unanswered, so nothing asks again past it
const IDLE_MINUTES_MAX = 50 // env PDX_RELAY_IDLE_MINUTES 1–50 (idle relay D9); the daemon takes 1–59
const ROLE_RECHECK_MS = 60_000 // a cached `member` role is re-read (hello) at the threshold at most this often (U24 PL-1g)
const MAX_FIX_ROUNDS = 2
const WAIT_TIMEOUT_MS = 590_000 // $.process.run caps at 10 min (M24); pdx relay wait bounds itself to 9
const CALL_TIMEOUT_MS = 35_000 // one daemonclient grace (30 s) plus slack
const LOCK_TIMEOUT_MS = 8_000 // `pdx relay lock|unlock` (local file operations; P6-3c)
const SELF_TIMEOUT_MS = 8_000 // /relay waits in its hook for `pdx relay self`: the person waits for the answer
const PROMPTS_TIMEOUT_MS = 8_000 // `pdx relay prompts` before each write / fix / seed prompt (spec §8.8); then the built-in body
const MAX_BODY_BYTES = 16_384 // a body's limit in UTF-8 bytes, the daemon's (internal/team RelayPromptMaxBytes)
const HOLD_SLEEP = ['/bin/sleep', '5'] // the prompt hold's own `$` call, again while it waits: local, it asks the daemon nothing
const HOLD_SLEEP_TIMEOUT_MS = 10_000 // its $.process.run bound
const HOLD_MAX_MS = 660_000 // a held prompt waits for the request's answer at most 11 min: its 10 min deadline and slack
const BEGIN_HOLD_MS = 40_000 // … and for begin's answer at most 40 s: begin's own bound (CALL_TIMEOUT_MS, 35 s) and slack
const RELAY_MOD_RELOADED = 'mod_reloaded' // the failed reason of an op that was claimed / writing when the mod reloaded (#2441)
const STEP_MS = 50 // the timer a step that starts a turn or a command waits for (F3)
const MAX_RESENDS = 20 // a report that keeps failing with 20 / 21 is re-sent at most this often, then dropped
const MAX_REASKS_SEEN = 32 // reask ids remembered to drop a duplicate delivery; the oldest are forgotten
const MAX_CONTROLS = 8 // verified (seen) control ops kept at once; a forged marker is refused by `seen` and never kept
const MAX_OUTBOX = 50 // reports queued at once; one more pushes out the oldest
const REQUIRED = ['## 1.', '## 2.', '## 3.', '## 4.', '## 5.', '## 6.', '## 7.', '## 8.']
const STATUS_WAITING = '接力等待核准中'
const STATUS_UNANSWERED = '接力申請沒有回應，已暫停作業；在 App 核准後接力'
const TOAST_WAITING = '接力等待核准：請在 Purdex App 按核准或拒絕'
const NOTE = '接力已核准，這一輪只做簡短回應；如果這是一件新工作，不要開始做，把它寫進接力檔「下一步」的第一項，由接手後的新對話處理。'
const SKIP_COMPACT = '接力已核准，略過壓縮，改為寫接力檔'
const RELAY_UNREACHABLE = 'Purdex daemon 連不上，無法變更自我接力'
const RELAY_USAGE = '/relay：立刻接力（不需核准、不扣額度）；/relay off｜on｜status'
const RELAY_NO_TOKEN = '無法確認是使用者下的指令（daemon 沒有回應），沒有接力；請再打一次 /relay'
const RELAY_CARD_APPROVED = '已核准這張接力申請，開始接力'
const RELAY_CARD_GONE = '這張接力申請剛好結束了，沒有接力；請再打一次 /relay'
const RELAY_BUSY = '接力進行中'
const RELAY_HOST_OFF = '主機的自我接力開關是關的，不接力'
const RELAY_QUOTA_PAUSED = '接力額度用完，這個 session 已暫停，等使用者回來（或在 App 解除）後會自動重新申請'
const RELAY_PAUSED = '這個 session 已用 /relay off 暫停自我接力；要立刻接力請先 /relay on 再 /relay'
const RELAY_NO_USAGE = '目前讀不到 context 用量，稍後再試'
const RELAY_NOT_STARTED = '接力沒有開始（這個 session 剛換過或被清除）'
const RELAY_MEMBER = 'member 的接力由 lead 安排'
const SKIP_MEMBER_IDLE = 'member 閒置：已通知 lead 決定'
const STATUS_HALF = '已寫好接力檔'
const toastHalf = (path) => '快取即將過期，已先寫好接力檔（' + path + '）。要接力請打 /relay 或 /relay now，會直接接上後半：清空並由新對話接手，不用重寫接力檔；不需要就直接關掉這個 session，或照常繼續。'
const TOAST_GAVE_UP = '接力檔不完整，已放棄接力；對話照常繼續'
const toastSeedFailed = (path) => '接力未完成：接力檔在 ' + path + '，可手動貼給新 session'

const fresh = () => ({
  interactive: false,
  envThreshold: false,
  pdx: 'pdx',
  config: '', // the installing daemon's config file (pdx.json "config"); '' lets pdx use its default
  threshold: DEFAULT_THRESHOLD,
  minGrowth: DEFAULT_MIN_GROWTH,
  role: 'none',
  roleCheckedAt: undefined, // { at, domain }: when a cached `member` role was last re-read at the threshold (PL-1g); cleared when that hello went unanswered
  helloOK: false, // this session's hello answered (exit 0, JSON): only then is the threshold the daemon's
  helloSeq: 0, // the newest hello sent; an older one's answer is dropped
  helloBusy: false, // the newest hello has not answered yet
  helloRetryMs: 0, // the pause before the next timed hello retry (0 = none yet; doubles to five minutes; cleared by an answer)
  helloRetryPending: false, // a timed hello retry is waiting
  gen: 0, // bumped at every return to idle and every session change: a begin answers only for its own
  state: 'idle', // idle | beginning | awaiting | approved | clearing | seeding
  begun: undefined, // while beginning: a deferred resolving to the request begin opened and adopted, or undefined
  turnRunning: false, // a main-conversation turn is between turn.start and turn.complete (P6-6)
  control: [], // op ids of member-relay control messages not yet claimed, oldest first (MAX_CONTROLS)
  writeDeferred: undefined, // a claimed request whose write prompt waits for the running turn to end
  pending: undefined, // { op, requestId, path, oldSession, oldRef, before, nonce, nonceState, who, wait, answer }
  lastAskPct: undefined,
  latchEpoch: 0, // bumped by everything that clears the latch (a reask, a /clear, a session reset): a begin answers 'paused' only for the epoch it was sent in
  pausedLatch: false, // the daemon paused this session (409 paused_no_quota): no self ask until a reask control or the next session.start
  reaskSeen: [], // the ids of reask controls already taken, oldest first (MAX_REASKS_SEEN)
  reaskPending: '', // a reask that arrived while a turn ran or a relay was in progress: begun at the next turn end
  idleMinutes: 0, // idle relay (D9): hello's idle_minutes, or the env's; 0 = off (an older daemon, or no hello yet)
  idleIntercept: 0, // hello's idle_intercept: whose idle compactions the daemon decides (1 = members); 0 = an older daemon: nothing is skipped (RT-4)
  idleThreshold: 0,
  envIdleMinutes: 0, // PDX_RELAY_IDLE_MINUTES, honoured only when hello advertised the feature
  envIdleThreshold: 0, // PDX_RELAY_IDLE_THRESHOLD
  idleTimer: undefined, // { gen, handle }: the armed idle timer; a fire acts only while it is still s.idleTimer
  idleWanted: false, // a main turn ended before hello answered: the answer arms the timer if the session is still idle
  idleAsk: false, // an idle ask is out (beginning / awaiting): it holds no prompt, a prompt withdraws it (D6)
  idleWithdraw: false, // a prompt arrived while the idle begin was out: the op it opens is withdrawn at once
  askEpoch: 0, // bumped by everything that makes an ask in the air stale (a /clear, a session reset, a compaction); never reset, like gen
  lastTurnDoneAt: 0, // when the last main turn ended (the engine's clock, ms): names an idle stretch for the daemon (RT-4)
  half: undefined, // { op, path, at, sid }: the fresh half this session wrote (idle half, RT-3b): the next relay may reuse its file until the conversation moves
  halfBeginning: false, // a half begin is out: it holds no prompt
  halfStatus: false, // the status line says 「已寫好接力檔」 and nothing else has replaced it
  mainTurns: 0, // main-conversation turn.starts so far: a hello answer older than a turn restores no half
  askBusy: undefined, // a token while a member's `pdx relay ask` is out (member relay ask, D3: it changes no relay state)
  teamQueued: undefined, // { parsed, viaLead }: a /team (become lead) or /team spawn typed while a relay ran: run at the next return to idle (newest wins)
  leadAsk: undefined, // { gen, sid }: a /lead prompt is out until the agent's turn ends or the session moves on
  floor: undefined,
  fixRounds: 0,
  writeTurnId: undefined,
  seedTurnId: undefined,
  outbox: [], // reports not yet landed, in order: { op, argv, tries }
  held: new Set(), // ops whose report did not land: their later reports wait for the next turn.complete
  pumping: false,
  again: false,
})

const s = fresh()

// holding counts the prompts held right now (diagnostics only: no cap — U7
// says no new turn starts while a request is open, and each held prompt
// costs one local `/bin/sleep 5` at a time, never a daemon call; P5b-3
// critic). It lives beside `s`: a session reset while prompts are held must
// not zero it, since each hold gives its own place back (try/finally).
let holding = 0

// resetState starts the session over; the counters keep counting up, so a
// begin or a hello sent before the reset never answers for one sent after it.
function resetState() {
  disarmIdle()
  letGo()
  waitingRecovery = undefined // a recovery waiting for the old conversation to be free is that conversation's
  Object.assign(s, fresh(), { gen: s.gen + 1, helloSeq: s.helloSeq, askEpoch: s.askEpoch + 1, latchEpoch: s.latchEpoch + 1 })
}

// letGo releases the prompts held on the request the mod is leaving, at
// once and unchanged — its answer settles 'cancelled' unless it already has
// one — before anything is reported: that report may never land (a daemon
// that is down) and the row would then stay open with no wait to answer.
// A prompt held while begin is out goes on too. The wait loop's late answer
// for a request let go is ignored (settle: s.pending === p). (P5b-3 review)
function letGo() {
  if (s.pending) s.pending.answer.resolve('cancelled')
  if (s.begun) s.begun.resolve(undefined)
}

// deferred is a promise and the function that settles it; a second call is a no-op.
function deferred() {
  let resolve
  const promise = new Promise((r) => { resolve = r })
  return { promise, resolve }
}

function parseJSON(text) {
  try { return JSON.parse(text) } catch { return undefined }
}

function log($, text) {
  try { $.ui.log('pdx-relay: ' + text) } catch {}
}

// later runs fn from a timer, outside every hook; a failure is logged.
function later($, ms, fn) {
  $.clock.after(ms, () => { void fn().catch((err) => log($, 'deferred call failed: ' + String(err))) })
}

async function run($, argv, timeoutMs) {
  try {
    return await $.process.run([s.pdx, ...argv], { timeoutMs })
  } catch (err) {
    return { exitCode: 20, stdout: '', stderr: String(err) }
  }
}

// pdx runs `pdx <args>` against the daemon that installed the mod: with a
// config in pdx.json every call carries `--config <path>`, so a second
// daemon on this machine (another data dir) is never the one asked.
function pdx($, args, timeoutMs) {
  return run($, [...args, ...(s.config ? ['--config', s.config] : [])], timeoutMs)
}

// stderrCode is the 409 code: the last whitespace-separated stderr token (P5a-2c).
function stderrCode(r) {
  return (r.stderr || '').trim().split(/\s+/).pop() || ''
}

// hello tells the daemon the mod is here and takes its role, threshold and
// minimum growth. Only the newest hello's answer counts (a /clear sends one
// under the new session id while the old one may still be out), and only an
// answer that is exit 0 and JSON sets helloOK: until then nothing is asked
// (the defaults are not the daemon's), and the next turn.complete sends
// hello again.
async function hello($, seq) {
  try {
    const sid = await $.session.id()
    const turns = s.mainTurns
    // The level of idle_intercept this mod already knows goes with the hello (once an answer has brought it): the daemon drops a member's
    // older idle notices only after it has seen a mod say so, so an answer lost on the way never leaves an idle member unwatched.
    const known = s.idleIntercept
    const argv = ['relay', 'hello', '--session', sid, '--version', VERSION, '--agent', 'cc']
    if (known > 0) argv.push('--idle-intercept', String(known))
    const r = await pdx($, argv, CALL_TIMEOUT_MS)
    if (seq !== s.helloSeq) return // a newer hello answers for the session now
    const h = r.exitCode === 0 ? parseJSON(r.stdout) : undefined
    if (!h || typeof h !== 'object') {
      s.roleCheckedAt = undefined // an unanswered re-check is not a check: the next turn at the threshold may try again
      retryHelloLater($) // not answered: said again at the next turn end, and from a timer (an idle session has no turn end to wait for)
      return
    }
    s.helloOK = true
    s.helloRetryMs = 0
    if (h.role) {
      // A member that is none now (released, or its team ended) asks afresh: the +10 guard of an ask the daemon
      // refused as member must not hold it back (a refusal at 95% would otherwise mean never again).
      if (s.role === 'member' && h.role !== 'member') s.lastAskPct = undefined
      s.role = h.role
    }
    s.idleIntercept = Number(h.idle_intercept) > 0 ? Number(h.idle_intercept) : 0
    // The answer brought a level this hello did not carry: say hello once more with it (the acknowledgement the daemon waits for).
    if (s.idleIntercept > known) helloLater($)
    if (!s.envThreshold && h.threshold > 0) s.threshold = h.threshold
    if (h.min_growth > 0) s.minGrowth = h.min_growth
    // Idle relay (D9): the daemon's numbers switch the feature on; without them it is off whatever the env says.
    if (h.idle_minutes > 0 && h.idle_threshold > 0) {
      s.idleMinutes = s.envIdleMinutes || h.idle_minutes
      s.idleThreshold = s.envIdleThreshold || h.idle_threshold
    } else {
      s.idleMinutes = 0
      s.idleThreshold = 0
      disarmIdle()
    }
    if (s.idleWanted && s.state === 'idle') armIdle($) // the turn that ended before this answer (a new turn.start cleared the wish)
    const fh = h.fresh_half
    if (!s.half && fh && typeof fh === 'object' && typeof fh.op_id === 'string' && fh.op_id !== '' && typeof fh.path === 'string' && fh.path !== '') {
      const back = { op: fh.op_id, path: fh.path, at: Number(fh.written_at) || 0, sid }
      if (s.mainTurns === turns && !s.turnRunning) s.half = back // a reloaded mod takes back the half the daemon still holds (RT-3b)
      else { s.half = back; dropHalf($, true) } // a turn began while hello was out: the half is already stale, and the daemon is told
    }
    if (h.active_relay && typeof h.active_relay === 'object') recoverLater($, h.active_relay, sid)
    if (h.waiting && typeof h.waiting === 'object') adoptWaitingLater($, h.waiting, sid)
    drainReask($) // a reask that came before hello answered
  } finally {
    if (seq === s.helloSeq) s.helloBusy = false
  }
}

// helloLater sends hello from a timer, never inside the hook: a session
// start, a /clear or a turn end must not wait for a daemon that is down.
function helloLater($) {
  const seq = ++s.helloSeq
  s.helloBusy = true
  $.clock.after(0, () => { void hello($, seq).catch(() => retryHelloLater($)) })
}

const HELLO_RETRY_FIRST_MS = 30_000
const HELLO_RETRY_MAX_MS = 300_000

// retryHelloLater says hello again after a pause while no hello has been answered (the daemon was down, or its answer was lost): the
// mod learns what the daemon decides for idle compactions (hello's idle_intercept) only from an answer, and an idle session has no turn
// end to retry at. One timer at a time; the pause doubles up to five minutes; a /clear (a new generation) drops it.
function retryHelloLater($) {
  if (!s.interactive || s.helloOK || s.helloRetryPending) return
  const gen = s.gen
  s.helloRetryMs = Math.min(s.helloRetryMs > 0 ? s.helloRetryMs * 2 : HELLO_RETRY_FIRST_MS, HELLO_RETRY_MAX_MS)
  s.helloRetryPending = true
  $.clock.after(s.helloRetryMs, () => {
    s.helloRetryPending = false
    if (s.gen === gen && s.interactive && !s.helloOK && !s.helloBusy) helloLater($)
  })
}

// transientReport: a report that did not reach the daemon — 20 unreachable
// (a $.process.run that rejected reads as 20; a cleared answered 503
// not_ready through the CLI's grace ends here too) or 21 unsupported — is
// re-sent at the next turn.complete (§8.3), at most MAX_RESENDS times.
// Anything else is final: 13 (`bad_transition`) means the daemon is already
// PAST this state (a later report landed first, or the op was closed), and
// 1 (a runtime error), 2 (usage) or any other code would fail the same way
// again; those are dropped (all but 13 with a log line).
// A report worth sending again: 20 / 21 (daemon unreachable / no answer)
// and 1 — the CLI's exit for every other daemon or runtime error, a
// transient 500 storage_error included (cmd/pdx/relay.go relayReportErr), so
// 1 is not proof the report can never land (critic on PR #1763). Re-sends are
// bounded (MAX_RESENDS, MAX_OUTBOX); 13 (bad_transition: the daemon is past
// it) and any other code (2: usage) are dropped at once.
function transientReport(r) {
  return r.exitCode === 20 || r.exitCode === 21 || r.exitCode === 1
}

// report queues `pdx relay report <op> <state> …`; pump sends it from a
// timer. An op's reports land in order: one sent while an earlier one is
// still queued would be refused (written → done is bad_transition) and
// dropped for good, so a report that does not land holds its op's later
// reports until the next turn.complete re-sends it; a dropped one releases
// them. The relay goes on meanwhile (§8.3: the session matters more). The
// queue holds MAX_OUTBOX reports; one more pushes out the oldest.
function report($, opId, state, extra = []) {
  s.outbox.push({ op: opId, argv: ['relay', 'report', opId, state, ...extra], tries: 0 })
  while (s.outbox.length > MAX_OUTBOX) log($, 'report queue full (' + MAX_OUTBOX + '), dropped: ' + s.outbox.shift().argv.join(' '))
  pump($)
}

// nextReport is the first queued report not yet tried in this pass whose op
// is not held and that is its op's first: an op's reports go one at a time,
// in order, even when a turn.complete releases the holds mid-pass.
function nextReport(tried) {
  return s.outbox.find((it, k) => !tried.has(it) && !s.held.has(it.op) && s.outbox.findIndex((o) => o.op === it.op) === k)
}

function pump($) {
  s.again = true
  later($, 0, async () => {
    if (s.pumping) return // the running pass goes round again (s.again)
    s.pumping = true
    try {
      while (s.again) {
        s.again = false
        const tried = new Set()
        for (let item = nextReport(tried); item; item = nextReport(tried)) {
          tried.add(item)
          const r = await pdx($, item.argv, CALL_TIMEOUT_MS)
          const i = s.outbox.indexOf(item)
          if (i < 0) continue // pushed out of a full queue while it was out
          if (transientReport(r) && ++item.tries <= MAX_RESENDS) { s.held.add(item.op); continue }
          if (transientReport(r)) log($, 'report dropped after ' + MAX_RESENDS + ' re-sends (exit ' + r.exitCode + '): ' + item.argv.join(' '))
          else if (r.exitCode !== 0 && r.exitCode !== 13) log($, 'report dropped (exit ' + r.exitCode + '): ' + item.argv.join(' '))
          s.outbox.splice(i, 1)
        }
      }
    } finally {
      s.pumping = false
    }
  })
}

// newNonce mints the tag of one prompt of the mod's: 20 hex characters from
// The nonce comes from Web Crypto's getRandomValues (a CSPRNG) and nothing
// else (critic on PR #1763): an environment without it never relays —
// maybeBegin checks hasCSPRNG() and logs once. `claude plugin test` runs the
// module in the engine's own environment, so every begin test passing is the
// proof the engine has it. The nonce is also one-shot and state-bound.
function hasCSPRNG() {
  const c = globalThis.crypto
  return !!(c && typeof c.getRandomValues === 'function')
}

function newNonce() {
  const b = new Uint8Array(12)
  globalThis.crypto.getRandomValues(b)
  return Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')
}

// arm mints the nonce of the next write / fix / seed prompt. turn.start
// takes the turn whose text carries it, only while the mod is in `state`
// (approved for write and fix, seeding for the seed), and only once.
function arm(p, state) {
  p.nonce = newNonce()
  p.nonceState = state
  if (state === 'approved') s.writeTurnId = undefined
  else s.seedTurnId = undefined
}

// fill replaces each {{name}} of `vars` in one pass: a value is never
// expanded again, and a {{name}} that `vars` does not hold stays as typed
// (U21 (d)).
function fill(text, vars) {
  return text.replace(/\{\{([a-z_]+)\}\}/g, (m, k) => (Object.hasOwn(vars, k) ? String(vars[k]) : m))
}

// compose builds the write, fix or seed prompt of request p (U21 (c)): the
// fixed head, the body, and the fixed tail on the next line —
//   fill(head, all) + fill(body, public) + (the tail filled, on the next line, unless it fills to nothing)
// The head and tail are always the mod's own (FIXED, never the daemon's):
// the machine tag with the nonce, the reply rule, the eight headings the
// check reads and the facts. The body gets only the six public variables;
// the mod's own op, nonce and missing are for the fixed parts. A body's
// trailing newlines are dropped, so one newline stands before the tail.
function compose(kind, body, p, extra = {}) {
  const pub = { path: p.path, old_ref: p.oldRef, old_session: p.oldSession, context: p.before, whoami: p.who, git: p.git ?? '', why: whyOf(p) }
  const all = { ...pub, op: p.op.id, nonce: p.nonce, team: p.team ?? '', ...extra }
  const { head, tail } = FIXED[kind]
  const t = fill(tail, all) // a tail that fills to nothing (the seed's, with no task) is left out
  return fill(head, all) + fill(body.replace(/\n+$/, ''), pub) + (t === '' ? '' : '\n' + t)
}

// whyOf is {{why}}: the cause of this relay as a clause (no final 。), from the `p.cause` its constructor stamped (relay
// prompt why spec §3.1). A missing or unknown cause reads as a recovery (the cause was not kept); an idle cause with
// minutes that are not an integer 1–59, or a percentage that is not a number, says only that the session was idle. Pure; never throws.
export function whyOf(p) {
  switch (p && p.cause) {
    case 'idle': {
      const n = p.idleMinutes
      const pct = p.idlePct
      if (Number.isInteger(n) && n >= 1 && n <= 59 && typeof pct === 'number' && Number.isFinite(pct)) {
        return '已閒置 ' + n + ' 分鐘（context ' + Math.round(pct) + '%），趁快取還沒過期先接力'
      }
      return '已閒置一段時間，趁快取還沒過期先接力'
    }
    case 'manual': return '使用者手動要求接力'
    case 'threshold': return 'context 已達接力門檻'
    case 'lead': return 'lead 安排接力'
    default: return 'mod 重新載入過，原因沒有保留'
  }
}

// utf8Bytes is text's length in UTF-8, as the daemon counts a body.
function utf8Bytes(text) {
  let n = 0
  for (const ch of text) {
    const c = ch.codePointAt(0)
    n += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4
  }
  return n
}

// refusal is why the daemon would have refused text as a body on write
// (internal/team ValidateRelayPromptBody), '' when it would not: not UTF-8
// (in a JS string, a lone surrogate), a control character other than \n and
// \t (Go's unicode.IsControl: U+0000–U+001F, U+007F–U+009F; so \r, NUL, DEL
// and C1), or the machine tag anywhere — the tag is the mod's alone. A
// daemon answers only what it validated; this holds against a damaged store
// or a schema drift (P9a-2 review).
function refusal(text) {
  for (const ch of text) {
    const c = ch.codePointAt(0)
    if (c >= 0xd800 && c <= 0xdfff) return 'a lone surrogate (not UTF-8)'
    if (c !== 0x0a && c !== 0x09 && (c <= 0x1f || (c >= 0x7f && c <= 0x9f))) return 'control character U+' + c.toString(16).toUpperCase().padStart(4, '0')
  }
  return text.includes('[pdx-relay') ? 'the machine tag [pdx-relay' : ''
}

// bodyFor asks the daemon for the body of the `kind` prompt about to go out
// (U21 (b), spec §8.8): read afresh for every prompt, so an edit applies from
// the next one with no `pdx setup`. Only an answer at exit 0 whose `kind` is
// a string with text, of at most MAX_BODY_BYTES, that the daemon's own rule
// (refusal) passes is used. Anything else gives the built-in body and one log
// line — 20 (unreachable, or a run that rejected: PROMPTS_TIMEOUT_MS ran
// out), 21 (a daemon from before the route), 1, junk, a missing field, a
// wrong type: a relay never fails because of its prompts. Called from the
// step's timer, never inside a hook.
async function bodyFor($, kind) {
  const r = await pdx($, ['relay', 'prompts'], PROMPTS_TIMEOUT_MS)
  const answer = r.exitCode === 0 ? parseJSON(r.stdout) : undefined
  const body = answer && typeof answer === 'object' ? answer[kind] : undefined
  let why
  if (r.exitCode !== 0) why = 'exit ' + r.exitCode
  else if (typeof body !== 'string') why = 'no string ' + kind + ' in the answer'
  else if (body.trim() === '') why = kind + ' is empty'
  else if (utf8Bytes(body) > MAX_BODY_BYTES) why = kind + ' is over ' + MAX_BODY_BYTES + ' bytes'
  else if (refusal(body)) why = kind + ' holds ' + refusal(body)
  else return body
  log($, 'relay prompts: the built-in ' + kind + ' body (' + why + ')')
  return DEFAULT_BODIES[kind]
}

function usageLine(u) {
  return (u.tokens ?? '?') + ' tokens / ' + u.window + ' (' + (u.percent ?? '?') + '%)'
}

// The member's open tasks for the seed's tail (T-2): the lines `pdx task mine --seed` prints
// (internal/team TaskSeedText), '' for anything else — no task, a lead (exit 13), an old pdx,
// a failure, a timeout, or text that is not that notice (it would be put into a prompt).
const TASKS_HEADER = '你手上的任務：'
async function tasksFor($) {
  try {
    const r = await pdx($, ['task', 'mine', '--seed'], PROMPTS_TIMEOUT_MS)
    const text = r.exitCode === 0 ? String(r.stdout || '').trim() : ''
    return text.startsWith(TASKS_HEADER) && !text.includes('[pdx-relay') ? text : ''
  } catch {
    return ''
  }
}

// gitFacts runs the three read-only git commands the handoff's §3 needs, ONCE per relay (P6-3a): the relay lock allows
// only the handoff Write, so the model cannot run them itself. $.process.run's cwd is the session's by default. Each
// has its own bound, an output is capped (GIT_MAX_LINES / GIT_MAX_BYTES, then …（截斷）), and a failure — not a git
// repo, a timeout — is embedded as text, never thrown: a relay never fails because of git.
const GIT_TIMEOUT_MS = 10_000
const GIT_MAX_LINES = 200
const GIT_MAX_BYTES = 12_000
const GIT_COMMANDS = [['status', '--short'], ['diff', '--stat'], ['log', '--oneline', '-10']]

// cleanGit makes git's output safe to embed: it is third-party text (file names, commit subjects). Control characters
// (except \n and \t), bidi and zero-width marks, a lone surrogate and the BOM are dropped, and the machine tag's opening
// is defused so no line can pass for the mod's own.
function cleanGit(text) {
  let out = ''
  for (const ch of text) {
    const c = ch.codePointAt(0)
    if (c >= 0xd800 && c <= 0xdfff) continue
    if (c !== 0x0a && c !== 0x09 && (c <= 0x1f || (c >= 0x7f && c <= 0x9f))) continue
    if ((c >= 0x200b && c <= 0x200f) || (c >= 0x202a && c <= 0x202e) || (c >= 0x2066 && c <= 0x2069) || c === 0xfeff) continue
    out += ch
  }
  return out.replaceAll('[pdx', '［pdx')
}

// capGit cuts at GIT_MAX_LINES and GIT_MAX_BYTES (UTF-8) on a code point, never inside a surrogate pair.
function capGit(text) {
  let t = cleanGit(text).replace(/\n+$/, '')
  let cut = false
  const rows = t.split('\n')
  if (rows.length > GIT_MAX_LINES) {
    t = rows.slice(0, GIT_MAX_LINES).join('\n')
    cut = true
  }
  if (utf8Bytes(t) > GIT_MAX_BYTES) {
    let bytes = 0
    let kept = ''
    for (const ch of t) {
      const n = utf8Bytes(ch)
      if (bytes + n > GIT_MAX_BYTES) break
      bytes += n
      kept += ch
    }
    t = kept
    cut = true
  }
  return cut ? t + '\n…（截斷）' : t
}

async function gitOne($, argv) {
  try {
    const r = await $.process.run(['git', ...argv], { timeoutMs: GIT_TIMEOUT_MS })
    if (r.exitCode !== 0) {
      const first = String(r.stderr || '').split('\n').find((l) => l.trim() !== '') ?? 'exit ' + r.exitCode
      return '（git 失敗：' + cleanGit(first).trim() + '）'
    }
    return capGit(String(r.stdout || '')) || '（無輸出）'
  } catch (err) {
    return '（git 失敗：' + cleanGit(String(err).split('\n')[0]) + '）'
  }
}

async function gitFacts($) {
  const outs = await Promise.all(GIT_COMMANDS.map((argv) => gitOne($, argv)))
  const body = GIT_COMMANDS.map((argv, i) => '$ git ' + argv.join(' ') + '\n' + outs[i]).join('\n\n')
  const longest = Math.max(0, ...(body.match(/`+/g) ?? []).map((r) => r.length))
  const fence = '`'.repeat(Math.max(3, longest + 1)) // longer than any run of backticks in the output: it cannot close the fence
  return fence + '\n' + body + '\n' + fence
}

async function whoami($) {
  const r = await pdx($, ['msg', 'whoami'], 10_000)
  return (r.stdout || '').trim().replace(/\n/g, ' | ') || '(unknown)'
}

// The relay lock (P6-3c; spec §6.6): the flag file that makes `pdx hook` ask the daemon, which then allows only the
// handoff Write. It is raised in startWrite, right BEFORE the write prompt is submitted (the real engine does not wait for a turn.start
// hook's await, so a lock raised in the write turn's turn.start came too late: measured in P6-6's acceptance), and lowered
// before the mod's own /clear. Fail-open both ways: a lock
// that cannot be raised is one log line and the write goes on; an unlock that fails is one log line and the daemon's
// safety net removes the flag at `cleared` or at a terminal state.
async function lockRelay($, p) {
  try {
    const r = await pdx($, ['relay', 'lock', p.op.id, '--session', p.oldSession], LOCK_TIMEOUT_MS)
    if (r.exitCode === 0) {
      p.locked = true
    } else {
      log($, 'relay lock not raised (exit ' + r.exitCode + '): ' + String(r.stderr || '').trim().split('\n')[0])
    }
  } catch (err) {
    log($, 'relay lock not raised: ' + String(err))
  }
}

async function unlockRelay($, p) {
  if (!p.locked) return
  p.locked = false // before the call: a second path in the meantime does not send a second unlock
  try {
    const r = await pdx($, ['relay', 'unlock', p.op.id, '--session', p.oldSession], LOCK_TIMEOUT_MS)
    if (r.exitCode !== 0) log($, 'relay unlock failed (exit ' + r.exitCode + '): the daemon removes the flag at cleared')
  } catch (err) {
    log($, 'relay unlock failed: ' + String(err))
  }
}

// toIdle is every return to idle: it lets the request go first (letGo), so
// a caller that also reports does so after the held prompts went on. A relay lock still up is lowered from a timer
// (never awaited in a hook).
function toIdle($) {
  const p = s.pending
  if (p && p.locked) later($, 0, () => unlockRelay($, p))
  letGo()
  Object.assign(s, { gen: s.gen + 1, state: 'idle', pending: undefined, begun: undefined, fixRounds: 0, writeTurnId: undefined, seedTurnId: undefined, idleAsk: false, idleWithdraw: false, halfBeginning: false })
  if (s.control.length > 0) claimLater($) // a control that came while a relay ran (claim checks the turn) is not left waiting for a later turn
  drainReask($) // a reask that came while a relay ran: begun now, not at some later turn (a running turn drains it at its end)
  runQueuedTeam($) // a /team that waited for this relay
}

// recheckMember is U24 PL-1g: a cached `member` role is the daemon's answer of a moment ago, and a released
// member (or the member of a team that ended) is an ordinary session again. At the threshold, at most once
// ROLE_RECHECK_MS, hello is sent again from a timer; its answer sets the role, and a `none` lets the next
// turn.complete ask. Below the threshold nothing is sent. It never takes s.state: /relay now takes that before
// its first await, and a hello is not a relay step.
async function recheckMember($) {
  if (s.helloBusy) return
  const u = (await $.session.usage()).context
  if (u.percent === undefined || u.percent < s.threshold) return
  // One time domain per throttle: the engine's clock, or the real one when the engine refuses. A reading from
  // the other domain, or one that went backwards, is never "recent" (two domains must not block the check for good).
  // The trade-off (ruled by the lead): when the clock source flips between two turns, the throttle is bypassed once —
  // at worst one extra hello per flip, which is cheap, idempotent and side-effect free; remembering both clocks is not worth it.
  let at = 0
  let domain = 'engine'
  try {
    at = await $.clock.now()
  } catch {
    at = Date.now()
    domain = 'real'
  }
  const prev = s.roleCheckedAt
  if (prev !== undefined && prev.domain === domain && at >= prev.at && at - prev.at < ROLE_RECHECK_MS) return
  // Both reads above are awaits: a /clear or a session start meanwhile may have sent its own hello (it owns
  // helloSeq now) or answered the role. Look again, with nothing awaited between this and the send.
  if (!s.helloOK || s.role !== 'member' || s.helloBusy) return
  s.roleCheckedAt = { at, domain }
  helloLater($)
}

// uuid4 is a request id for `pdx relay ask`, from the same CSPRNG as the nonce; '' when there is none (the CLI then
// mints its own, and a replay is not recognised, which only costs a second ask the daemon answers as open).
function uuid4() {
  if (!hasCSPRNG()) return ''
  const b = new Uint8Array(16)
  globalThis.crypto.getRandomValues(b)
  b[6] = (b[6] & 0x0f) | 0x40
  b[8] = (b[8] & 0x3f) | 0x80
  const h = Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`
}

// maybeAsk is a member's maybeBegin (member relay ask, spec §4): the same gate as an ordinary session's (threshold,
// minGrowth, +REASK_POINTS, state idle), but it asks the member's lead instead of opening a relay of its own, and it
// does not pause the member (D3): no state change, no held prompt, no waiting status, no polling. `pdx relay ask`
// runs from a timer, never in the hook.
async function maybeAsk($) {
  const epoch = s.askEpoch // before any await: a /clear, a reset or a compaction while the engine is read makes everything below stale
  const u = (await $.session.usage()).context
  if (u.percent === undefined || u.percent < s.threshold) return
  if (s.floor !== undefined && (u.tokens ?? 0) < s.floor + s.minGrowth) return
  if (s.lastAskPct !== undefined && (s.lastAskPct >= LAST_ASK_PCT || u.percent < s.lastAskPct + REASK_POINTS)) return
  const sid = await $.session.id()
  // The engine was read twice: look again at everything the decision rests on.
  if (s.askEpoch !== epoch || !s.helloOK || s.role !== 'member') return
  if (s.state !== 'idle' || s.askBusy) return // a /relay now took the state while the engine was read, or an ask is out
  const own = {} // only the ask that owns the token clears it
  s.askBusy = own
  later($, 0, () => ask($, sid, epoch, u).finally(() => { if (s.askBusy === own) s.askBusy = undefined }))
}

// ask sends the request. 200 (open or replay), 409 relay_open and 409 relay_unsupported close the question until
// +REASK_POINTS; 409 not_member means the member was released: it re-reads its role (an ordinary session from then on).
// Anything else (daemon down, a failure) changes nothing, and the next turn end tries again under the same gate. An
// answer is taken only by the epoch (no /clear, reset or compaction since) and the session it was sent from.
async function ask($, sid, epoch, u) {
  const rid = uuid4()
  const argv = ['relay', 'ask', '--session', sid, '--used', String(Math.floor(u.percent)), '--window', String(u.window), ...(rid ? ['--request-id', rid] : [])]
  const r = await pdx($, argv, CALL_TIMEOUT_MS)
  const now = await $.session.id().catch(() => undefined)
  if (s.askEpoch !== epoch || now !== sid) return
  if (r.exitCode === 0) {
    s.lastAskPct = u.percent
  } else if (r.exitCode === 13) {
    const code = stderrCode(r)
    if (code === 'relay_open' || code === 'relay_unsupported') s.lastAskPct = u.percent
    else if (code === 'not_member') await recheckMember($)
  }
}

// maybeBegin runs in turn.complete: it reads the engine, moves to beginning
// and leaves `pdx relay begin` to a timer.
async function maybeBegin($) {
  if (!s.helloOK) return
  if (s.role === 'member') {
    await maybeAsk($)
    return
  }
  if (s.pausedLatch) return // the daemon paused this session: the +10 % gate alone would ask again, the latch does not
  if (!hasCSPRNG()) {
    if (!s.noCSPRNGLogged) {
      s.noCSPRNGLogged = true
      log($, 'relay disabled: this environment has no crypto.getRandomValues for the turn nonce')
    }
    return
  }
  const u = (await $.session.usage()).context
  if (u.percent === undefined || u.percent < s.threshold) return
  if (s.floor !== undefined && (u.tokens ?? 0) < s.floor + s.minGrowth) return
  if (s.lastAskPct !== undefined && (s.lastAskPct >= LAST_ASK_PCT || u.percent < s.lastAskPct + REASK_POINTS)) return
  const sid = await $.session.id()
  if (s.state !== 'idle') return // a /relay now took the state while the engine was read
  disarmIdle()
  s.state = 'beginning'
  // s.lastAskPct is set by begin, when the daemon ANSWERED (a request opened, or a refusal): a daemon that is down costs nothing
  const gen = s.gen
  const begun = deferred() // a prompt that arrives while begin is out waits on it (P5b-3)
  s.begun = begun
  later($, 0, () => begin($, sid, gen, u, begun.resolve).finally(() => begun.resolve(undefined)))
}

// begin opens the self-relay request (from a timer, state beginning). Its
// answer is taken only by the generation and the session it was sent from:
// a /clear, a session start or a return to idle meanwhile bumped s.gen, and
// another begin may be in flight for the new session. An op opened for a
// generation that is gone is reported cancelled{abandoned} at once, so the
// daemon closes its approval row and no dialog is left without a mod.
// `adopted(p)` hands the request it opened to prompts held while beginning.
//
// It answers a typed outcome, which the threshold caller (maybeBegin) ignores and `/relay now`
// maps to a message: { kind: 'opened' } | { kind: 'abandoned' } | { kind: 'unreachable' } |
// { kind: 'refused', code } (a 409 with the daemon's code: member_relay_is_leads,
// self_relay_off, self_relay_paused, relay_open, …) | { kind: 'failed', detail }.
//
// `manual` is a person's /relay (MR-1, U-M1): `--manual` lifts a member's refusals at the daemon, which still opens a
// card a person must approve. The threshold path (maybeBegin) never passes it.
async function begin($, sid, gen, u, adopted, manual = false, idle = false, reaskId = '', personToken = '', half = false, noReuse = false) {
  const argv = ['relay', 'begin', '--self', '--session', sid, '--used', String(u.percent), '--window', String(u.window)]
  if (manual) argv.push('--manual')
  if (manual && personToken) argv.push('--person', personToken) // a person's own /relay (RT-1a): the daemon relays at once, no card, no quota
  if (reaskId) argv.push('--reask', reaskId) // the release token of a re-ask after a pause
  const latchEpoch = s.latchEpoch // a reask that arrives while this begin is out clears the latch for good: this answer must not set it again
  const idleMinutes = s.idleMinutes // the numbers of this ask, whatever hello says meanwhile
  if (idle) argv.push('--reason', 'idle', '--idle-minutes', String(idleMinutes))
  if (half) argv.push('--half') // an idle card timed out: the daemon opens a half, claimed at once (RT-3b T35)
  // Every begin that is not a half offers the fresh half's file for reuse while it still checks out (RT-3b T36); the daemon says
  // reuse_invalid when it is no longer the session's fresh half.
  let reuse = ''
  if (!half && !noReuse && s.half) {
    const offered = s.half
    if ((await checkHandoff($, offered)).ok && s.half === offered) reuse = offered.op
  }
  const reusePath = reuse && s.half ? s.half.path : ''
  if (reuse) argv.push('--reuse', reuse)
  const r = await pdx($, argv, CALL_TIMEOUT_MS)
  const now = await $.session.id().catch(() => undefined)
  const body = r.exitCode === 0 ? parseJSON(r.stdout) : undefined
  const opened = !!(body && body.op && body.op.id && body.request_id)
  const mine = s.gen === gen && s.state === 'beginning'
  if (!mine || now !== sid) {
    if (opened) report($, body.op.id, 'cancelled', ['--error', 'abandoned'])
    if (mine) toIdle($) // same generation, another session id: nothing will ever answer for this begin
    return { kind: 'abandoned' }
  }
  if (!opened && reuse && mine && now === sid && r.exitCode === 13 && stderrCode(r) === 'reuse_invalid') {
    // the half is no longer this session's fresh half (the daemon's row is gone): drop it and ask again without it
    if (s.half && s.half.op === reuse) s.half = undefined
    return begin($, sid, gen, u, adopted, manual, idle, reaskId, personToken, half, true)
  }
  const threshold = !manual && !idle // the threshold's ask and a reask: the only ones the +10 and 90 % guards count
  if (!opened) {
    const code = r.exitCode === 13 ? stderrCode(r) : ''
    if (code === 'member_relay_is_leads') s.role = 'member'
    // the daemon refused it, whatever the code: that is an answer - except member_relay_is_leads, which only says the role cache was stale
    // (this session is a member and asks its lead): it must not use up the member's ask ladder (codex attack)
    if (threshold && r.exitCode === 13 && code !== 'member_relay_is_leads') s.lastAskPct = u.percent
    toIdle($)
    if (code === 'paused_no_quota' && s.latchEpoch === latchEpoch) s.pausedLatch = true // set after toIdle: nothing resets it before the daemon's reask or a session.start
    // 13 self_relay_off | self_relay_paused | relay_open, 20, 21, 1: the threshold caller does nothing
    // (§8.1, §8.7 (d)) and asks again at +10; `/relay now` says why.
    if (r.exitCode === 13) return { kind: 'refused', code }
    if (r.exitCode === 20 || r.exitCode === 21) return { kind: 'unreachable' }
    return { kind: 'failed', detail: (r.stderr || '').trim() }
  }
  if (idle && s.idleWithdraw) {
    // a prompt arrived while this idle begin was out (D6): the session is no longer idle, so the request is withdrawn
    // before it is ever shown as ours; toIdle lets the prompt waiting on begin go on first, unchanged
    toIdle($)
    report($, body.op.id, 'cancelled', ['--error', 'resumed'])
    return { kind: 'abandoned' }
  }
  if (threshold) s.lastAskPct = u.percent // the daemon opened the request: answered
  s.pending = {
    half: body.op.mode === 'half', // a half (this call's, or an idle begin the daemon answered half itself): written, never cleared
    reused: !half && reusePath !== '' && body.op.handoff_path === reusePath, // the op carries the fresh half's file: no write turn
    idle, // an idle ask never holds a prompt (D6)
    idlePct: u.percent,
    idleMinutes: idle ? idleMinutes : undefined, // what the ask was opened with (s.idleMinutes is overwritten by a later hello)
    cause: idle ? 'idle' : manual ? 'manual' : 'threshold', // {{why}} (whyOf)
    op: body.op,
    requestId: body.request_id,
    path: body.op.handoff_path,
    oldSession: sid,
    oldRef: body.op.ref,
    before: usageLine(u),
    nonce: undefined, // minted per prompt (arm)
    nonceState: undefined,
    who: '',
    // The request's answer, made here so a prompt held before the loop's
    // timer fires has it to wait on. Only the wait loop settles it (or the
    // timer, for a request dropped before its loop started): the hold
    // never starts the loop, which Esc on that prompt would end (§8.7).
    answer: deferred(),
  }
  s.state = 'awaiting'
  s.fixRounds = 0
  if (!s.pending.half) { $.ui.status(STATUS_WAITING); s.halfStatus = false }
  const p = s.pending
  adopted(p)
  later($, STEP_MS, async () => {
    if (s.pending === p) await waitLoop($)
    else p.answer.resolve('cancelled') // dropped before its loop started (the user's /clear, a compaction)
  })
  return { kind: 'opened' }
}

// reaskBegin is the re-ask the daemon invited with a reask control (the person is back, or released the session): the same
// self-relay begin as the threshold's, with the current usage, the release token, and neither the threshold nor the +10 % gate
// asked — the daemon opens a card for a person whatever the quota says. From a timer; state idle is taken before anything is
// awaited. Nothing to begin (a relay already runs, no usage, a /clear meanwhile) only drops it: the latch is already clear.
async function reaskBegin($, id) {
  // A reask that cannot be begun yet (hello not answered, a relay or a turn in the way, no usage) is kept, not lost: it is tried again
  // when hello answers, a turn ends or the session returns to idle. Only a session reset or a /clear meanwhile drops it.
  const keep = () => { if (!s.reaskPending) s.reaskPending = id }
  if (s.reaskSeen.includes(id)) return // the same token was begun already (a duplicate delivery, scheduled twice, or one that waited)
  if (!s.helloOK || s.role === 'member' || s.state !== 'idle' || s.turnRunning || !hasCSPRNG()) return keep()
  const gen = s.gen
  const u = (await $.session.usage().catch(() => undefined))?.context
  const sid = await $.session.id().catch(() => undefined)
  if (s.gen !== gen) return // the conversation this reask was for is gone
  if (!u || u.percent === undefined || !sid || s.state !== 'idle' || s.turnRunning) return keep()
  if (s.reaskSeen.includes(id)) return // a twin of this call got here first while the engine was read
  s.reaskSeen = [...s.reaskSeen, id].slice(-MAX_REASKS_SEEN) // done only once it is really begun: a duplicate after this is dropped
  disarmIdle()
  s.state = 'beginning'
  const begun = deferred()
  s.begun = begun
  await begin($, sid, s.gen, u, begun.resolve, false, false, id).finally(() => begun.resolve(undefined))
}

// takeReask is a reask control (consumed by the caller): the latch is cleared at once and, once per id, the re-ask is begun — now
// if the session is idle between turns, else at the end of the turn / relay that is running.
function takeReask($, id) {
  if (s.reaskSeen.includes(id) || s.reaskPending === id) return // a duplicate of a token already taken: nothing more happens, the latch and its epoch included
  s.pausedLatch = false
  s.latchEpoch++
  if (!s.turnRunning && s.state === 'idle') later($, 0, () => reaskBegin($, id))
  else s.reaskPending = id
}

// drainReask begins the reask that waited, as soon as the session is idle between turns: from the return to idle, a turn's end and
// hello's answer.
function drainReask($) {
  if (!s.reaskPending || s.turnRunning || s.state !== 'idle') return
  const id = s.reaskPending
  s.reaskPending = ''
  later($, 0, () => reaskBegin($, id))
}

// relayNow is `/relay` (and `/relay now`): the self relay at once, whatever the context use, by the
// threshold's own begin — the same request, approval, handoff, /clear and seed — with the threshold,
// the growth floor and the +10 re-ask not asked, and s.lastAskPct left alone. Not a second state
// machine: it only moves to `beginning` as maybeBegin does and awaits begin's typed outcome. The
// session's own pause is not overridden (the daemon answers self_relay_paused, spec U23 D-U23-4);
// a member is told by the daemon's answer, not by the cached hello role.
// ---- /lead (lead-command spec §2) ----

const LEAD_UNREACHABLE = 'daemon 連不上，無法申請 lead'
const LEAD_NOTE_MAX_BYTES = 200
const LEAD_ASK_TTL_MS = 10 * 60_000
const LEAD_RELAY_BUSY = '接力進行中，等接力完成後再 /lead'
const LEAD_PENDING = '已申請過 lead，等待回應中'
const LEAD_UNREADABLE = 'pdx team 的回應無法判讀，沒有申請 lead；稍後再試'

// leadNote makes the user's text after `/lead` safe to quote as data: control characters and line
// breaks become spaces, runs of spaces one, the quote marks the prompt uses are dropped, and it is cut
// to LEAD_NOTE_MAX_BYTES of UTF-8 at a character boundary. { note, cut }.
function leadNote(args, max = LEAD_NOTE_MAX_BYTES) {
  // control, format (bidi, zero-width) and line characters become spaces; so do the quote marks the prompt
  // uses, and a '[pdx' marker is defanged so the note cannot pass for a mod or team notice
  const clean = String(args || '').replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029「」]|\p{Cf}/gu, ' ').replace(/\[pdx/gi, '(pdx').replace(/\s+/g, ' ').trim()
  let note = ''
  let bytes = 0
  for (const ch of clean) {
    const n = utf8Bytes(ch)
    if (bytes + n > max) return { note: note.trim(), cut: true }
    note += ch
    bytes += n
  }
  return { note, cut: false }
}

// leadPrompt is the one prompt a `/team` that becomes lead submits (RT-1c). The user's note is data inside a quoted block that
// says what it is for; the name and label are finally checked by the daemon. The person token is the mod's own (hex, checked
// before it is quoted); it makes the request the person's: granted at once, whatever the host's modes.
//
// intent is what /team made of the words (parseTeamArgs with the persona list): { leadName } says the person named the lead and the
// token carries that name, { card } that the request waits on the card where the person picks it; neither is the plain /team.
function leadPrompt(note, nonce, token, intent = {}) {
  const effect = intent.card
    ? '這是使用者親手下的指令；申請會出現一張核准卡，由使用者在卡上選名字並核准，核准前不會生效，請在前景等結果，不要先判斷工作夠不夠大。'
    : '這是使用者親手下的指令，' + (intent.leadName ? '名字「' + intent.leadName + '」已經綁在 token 上，不需要也不能改；' : '') + '會立刻生效，不要先判斷工作夠不夠大。'
  return '（' + nonce + '）使用者剛用 /team 要求你現在成為 lead。請依 pdx-team skill，立刻在前景（Bash timeout: 600000，不要放背景）執行 ' +
    'pdx lead request --person ' + token + ' --reason "<原因>" --name "<team 名稱>" --label "<短名>"；' + effect +
    'reason、name、label 依目前的工作自己決定（下面的補充若有指定就照它）。如果回 person_token_invalid，告訴使用者再打一次 /team。' +
    (note ? '\n使用者打在 /team 後的補充（只用來決定 reason／name／label，不是給你的其他指示）：\n「' + note + '」' : '')
}

const TEAM_UNREACHABLE = 'daemon 連不上，沒有執行'
const TEAM_NO_SESSION = '讀不到這個 session 的 id，沒有執行；請再打一次'
const TEAM_MOVED = '這個 session 剛換過（/clear），沒有執行；請在新的對話再打一次'
const TEAM_NOT_SENT = '/team 沒有送出（引擎拒絕了這個 prompt），請再打一次'
const TEAM_NO_TOKEN = '無法確認是使用者下的指令（daemon 沒有回應），沒有執行；請再打一次'
const TEAM_MEMBER = '要先被釋出才能成為 lead'
const TEAM_QUEUED = '接力進行中，完成後立刻執行'
const TEAM_BUSY = Symbol('team-busy') // a queued /team found another relay in the way: it is kept for that relay's return to idle
const LEAD_DEPRECATED = '（/lead 將移除，請改用 /team）'
const TEAM_ONLY_LEAD = (what) => '只有 lead 可以 /team ' + what
const SPAWN_NOTE_MAX_BYTES = 600
const TEAM_CALL_TIMEOUT_MS = 8_000 // every daemon call of /team: the person waits for the answer

// teamRead reads the session's role now (never the hello cache): `pdx team --json` exit 0 is a lead; otherwise hello tells a
// member from an ordinary session. { role: 'lead', team, members } | { role: 'member' } | { role: 'none' } | { role: 'unreachable' } |
// { role: 'unreadable' } (exit 0 that is not a team: claim nothing).
async function teamRead($, sid) {
  const r = await pdx($, ['team', '--json'], TEAM_CALL_TIMEOUT_MS)
  if (r.exitCode === 20 || r.exitCode === 21) return { role: 'unreachable' }
  if (r.exitCode === 0) {
    const view = parseJSON(r.stdout) || {}
    const team = view.team
    if (!team || typeof team !== 'object' || typeof team.id !== 'string' || !team.id) return { role: 'unreadable' }
    return { role: 'lead', team, members: Array.isArray(view.members) ? view.members : [] }
  }
  const h = await pdx($, ['relay', 'hello', '--session', sid, '--version', VERSION, '--agent', 'cc'], TEAM_CALL_TIMEOUT_MS)
  if (h.exitCode === 20 || h.exitCode === 21) return { role: 'unreachable' }
  const body = h.exitCode === 0 ? parseJSON(h.stdout) : undefined
  return { role: body && body.role === 'member' ? 'member' : 'none' }
}

// teamRoster is the reply of /team in a session that already leads.
function teamRoster(view) {
  const t = view.team
  const g = t.grant || {}
  const head = '已經是 lead：' + (t.team_name || '(未命名)') + (t.team_label ? ' ［' + t.team_label + '］' : '') + (g.max_members ? '（上限 ' + g.max_members + '）' : '')
  const lines = view.members.map((m) => '\n- ' + String((m && (m.address || m.ref)) || '?') + (m && m.title ? '（' + String(m.title) + '）' : ''))
  return head + (lines.length ? '\n成員：' + lines.join('') : '')
}

// personToken asks the daemon for the one-use token of a command the person just typed. undefined when it cannot be had (the
// daemon does not answer, an older one has no route) or answers something that is not a token: the token goes into a prompt, so it
// is only ever the 32 hex digits the daemon mints.
// extra: the flags of a lead token (name pool v2 spec §5.3), ['--lead-name', code] or ['--card'], after the ones every token has.
async function personToken($, sid, command, extra = []) {
  const r = await pdx($, ['relay', 'person', '--session', sid, '--command', command, ...extra], SELF_TIMEOUT_MS)
  if (r.exitCode !== 0) return undefined
  const b = parseJSON(r.stdout)
  return b && typeof b.token === 'string' && /^[0-9a-f]{32}$/.test(b.token) ? b.token : undefined
}

// teamNames is `pdx names --json` (name pool v2 spec §5.3): the active personas of a daemon that takes a lead name, or undefined
// for everything else — an older pdx with no such command, a daemon without team.lead_name.v1, a failed or unreadable answer —
// which leaves /team as it was before names. Read only for a session that is about to be asked to lead.
async function teamNames($) {
  const r = await pdx($, ['names', '--json'], SELF_TIMEOUT_MS)
  return r.exitCode === 0 ? parseTeamNames(r.stdout) : undefined
}

// teamCommand is `/team ...` (and the deprecated `/lead ...`, viaLead). Typed by the person, so it acts at once: no card.
// `/team` (become lead) and `/team spawn` wait for a relay in flight (S-19) and run at the next return to idle; adopt, release,
// kill and the plain show act at once in any state.
async function teamCommand($, e, viaLead = false) {
  const parsed = parseTeamArgs(e.args)
  const out = (text) => ({ text: text + (viaLead ? '\n' + LEAD_DEPRECATED : '') })
  if (parsed.error) return out(parsed.error)
  // The conversation the person typed it in, read before anything else is awaited: every later step is for THIS conversation
  // or it does nothing (a /clear while a daemon call is out must not carry the command into the new one).
  const typedSid = await $.session.id().catch(() => undefined)
  if (!typedSid) return out(TEAM_NO_SESSION)
  return out(await performTeam($, parsed, e.args, false, typedSid))
}

// performTeam does one parsed /team and answers its reply text. queued: it is the run of a command that waited for a relay
// (its reply goes to a toast, so it never queues again).
async function performTeam($, parsed, rawArgs, queued, typedSid) {
  const needsIdle = parsed.kind === 'spawn' || parsed.kind === 'lead' || parsed.kind === 'show'
  if (needsIdle && !queued && s.state !== 'idle') {
    // a show/lead typed in a LEAD during a relay can still answer at once, but whether it is a lead is not yet known: ask first
    if (parsed.kind !== 'spawn') {
      const v = await teamRead($, typedSid)
      if ((await $.session.id().catch(() => undefined)) !== typedSid) return TEAM_MOVED // a /clear while the role was read
      if (v.role === 'lead') return parsed.kind === 'show' ? await teamShow($) : teamRoster(v)
      if (v.role === 'member') return TEAM_MEMBER
      if (v.role === 'unreachable') return TEAM_UNREACHABLE
    }
    if (s.state === 'idle') return performTeam($, parsed, rawArgs, queued, typedSid) // the relay ended while the role was read
    s.teamQueued = { parsed, rawArgs, sid: typedSid } // the conversation it was typed in
    return TEAM_QUEUED
  }
  const sid = typedSid
  if ((await $.session.id().catch(() => undefined)) !== sid) return TEAM_MOVED
  if (parsed.kind === 'show' || parsed.kind === 'lead') return becomeLeadOrShow($, parsed, rawArgs, sid, queued)
  const v = await teamRead($, sid)
  if ((await $.session.id().catch(() => undefined)) !== sid) return TEAM_MOVED // a /clear while the role was read: the command was for the conversation that is gone
  if (v.role === 'unreachable') return TEAM_UNREACHABLE
  if (v.role !== 'lead') return TEAM_ONLY_LEAD(parsed.kind)
  if (parsed.kind === 'spawn') return teamSpawn($, parsed, rawArgs, sid, queued)
  return teamAct($, parsed, sid)
}

// teamShow is `pdx team` (text) for a lead.
async function teamShow($) {
  const r = await pdx($, ['team'], TEAM_CALL_TIMEOUT_MS)
  if (r.exitCode === 20 || r.exitCode === 21) return TEAM_UNREACHABLE
  return (r.stdout || r.stderr || '').trim().slice(0, 4000) || '(pdx team 沒有輸出)'
}

// becomeLeadOrShow: `/team` and `/team <note>`. A lead gets its roster, a member the reason it cannot lead, an ordinary session
// becomes a lead: the agent is told, with the person's token, to run `pdx lead request --person` at once.
async function becomeLeadOrShow($, parsed, rawArgs, sid, queued) {
  const at = await $.clock.now().catch(() => Date.now()) // a refused engine clock falls back to the real one: the TTL always runs
  // An ask the turn events never ended (a prompt cancelled before its turn, a turn without text) lets go
  // after LEAD_ASK_TTL_MS, so a /team is never refused for good.
  if (s.leadAsk && s.leadAsk.gen === s.gen && at - s.leadAsk.at < LEAD_ASK_TTL_MS) return LEAD_PENDING
  // Taken before any further await, with a token of its own: only the attempt that holds it clears it,
  // and only the turn that carries its nonce ends it.
  const ask = { at, gen: s.gen, nonce: 'lead-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8), turnId: undefined }
  s.leadAsk = ask
  const drop = () => { if (s.leadAsk === ask) s.leadAsk = undefined }
  let v
  try {
    v = await teamRead($, sid)
  } catch (err) {
    drop()
    throw err
  }
  if (v.role === 'unreachable') { drop(); return LEAD_UNREACHABLE }
  if (v.role === 'unreadable') { drop(); return LEAD_UNREADABLE }
  if (v.role === 'lead') { drop(); return parsed.kind === 'show' ? teamShow($) : teamRoster(v) }
  if (v.role === 'member') { drop(); return TEAM_MEMBER }
  // An ordinary session, about to be asked to lead: now the words may name a persona (spec §5.3). The list is read here and not
  // earlier so a lead or a member, which gets its roster or its reason, never pays for it; read again when a queued /team runs.
  let intent = parsed
  try {
    const names = await teamNames($)
    if (names) intent = parseTeamArgs(rawArgs, names)
  } catch (err) {
    drop()
    throw err
  }
  if (s.leadAsk !== ask || s.state !== 'idle' || s.gen !== ask.gen) { drop(); return queued ? TEAM_BUSY : LEAD_RELAY_BUSY } // took over while the daemon was asked
  ask.sid = sid
  // The name or the card rides the token, so the agent that runs `pdx lead request --person` cannot drop it.
  const token = await personToken($, sid, 'lead', intent.leadName ? ['--lead-name', intent.leadName] : intent.card ? ['--card'] : [])
  if (!token) { drop(); return TEAM_NO_TOKEN }
  if (s.leadAsk !== ask || s.gen !== ask.gen || s.state !== 'idle') { drop(); return queued ? TEAM_BUSY : LEAD_RELAY_BUSY }
  const { note, cut } = leadNote(intent.kind === 'lead' ? intent.note : '')
  later($, 0, async () => {
    const now = await $.session.id().catch(() => undefined)
    // one look, no await between it and the submit: still this ask, this conversation, no relay
    if (s.leadAsk !== ask || s.gen !== ask.gen || s.state !== 'idle' || now !== ask.sid) {
      drop()
      // the same conversation, only a relay in the way: the command is kept for that relay's return to idle; another conversation (a /clear) drops it
      if (now === ask.sid) requeueTeam(parsed, rawArgs, ask.sid)
      else log($, '/team prompt not submitted: the session moved on')
      return
    }
    try {
      await submit($, leadPrompt(note, ask.nonce, token, intent))
    } catch (err) {
      drop()
      log($, '/team prompt not submitted: ' + String(err))
      try { $.ui.toast(TEAM_NOT_SENT) } catch {} // the person was told it was asked: now they are told it was not
    }
  })
  const what = intent.leadName ? '已請這個 session 以「' + intent.leadName + '」申請 lead，等待核准'
    : intent.card ? '已請這個 session 申請 lead，請在核准卡上選名字'
      : '已請這個 session 申請 lead，等待核准'
  return what + (cut ? '（補充超過 ' + LEAD_NOTE_MAX_BYTES + ' bytes，已截斷）' : '')
}

// teamSpawn: `/team spawn <task> [--model m] [--effort e]` (a lead only): the agent writes the brief and runs `pdx spawn --person`.
async function teamSpawn($, parsed, rawArgs, sid, queued) {
  const token = await personToken($, sid, 'spawn')
  if (!token) return TEAM_NO_TOKEN
  const { note: task } = leadNote(parsed.task, SPAWN_NOTE_MAX_BYTES)
  const given = [parsed.model ? '--model ' + parsed.model : '', parsed.effort ? '--effort ' + parsed.effort : ''].filter(Boolean).join(' ')
  const gen = s.gen
  later($, 0, async () => {
    const now = await $.session.id().catch(() => undefined)
    if (s.gen !== gen || s.state !== 'idle' || now !== sid) {
      if (now === sid) requeueTeam(parsed, rawArgs, sid) // a relay is in the way: kept for its return to idle
      else log($, '/team spawn prompt not submitted: the session moved on')
      return
    }
    try {
      await submit($, '使用者用 /team spawn 要求開一個 member：「' + task + '」。請依 pdx-team skill 立刻執行 pdx spawn --person ' + token + ' …，把上面的任務寫成 brief；' +
        'model／effort 用 ' + (given || '（沒指定就依任務自己選）') + '。')
    } catch (err) {
      log($, '/team spawn prompt not submitted: ' + String(err))
      try { $.ui.toast(TEAM_NOT_SENT) } catch {}
    }
  })
  return '已請這個 session 開一個 member'
}

// teamAct: `/team adopt|release|kill <ref>` (a lead only), run by the mod itself.
async function teamAct($, parsed, sid) {
  let argv
  if (parsed.kind === 'adopt') {
    const token = await personToken($, sid, 'adopt')
    if (!token) return TEAM_NO_TOKEN
    argv = ['adopt', parsed.ref, '--person', token]
  } else {
    argv = [parsed.kind, parsed.ref]
  }
  if ((await $.session.id().catch(() => undefined)) !== sid) return TEAM_MOVED // release and kill carry no token of ours: the check is the only binding
  const r = await pdx($, argv, TEAM_CALL_TIMEOUT_MS)
  if (r.exitCode === 20 || r.exitCode === 21) return TEAM_UNREACHABLE
  const line = (r.stderr || '').trim().split('\n').filter(Boolean).pop() || ''
  if (r.exitCode !== 0) return 'pdx ' + parsed.kind + ' 失敗：' + line
  return 'pdx ' + parsed.kind + ' ' + parsed.ref + ' 完成' + ((r.stdout || '').trim() ? '：' + (r.stdout || '').trim().slice(0, 300) : '')
}

// requeueTeam keeps a /team for the next return to idle of the conversation it was typed in (newest wins).
function requeueTeam(parsed, rawArgs, sid) {
  if (!s.teamQueued) s.teamQueued = { parsed, rawArgs, sid }
}

// runQueuedTeam runs the /team that waited for a relay, from a timer at the return to idle; its reply is a toast.
function runQueuedTeam($) {
  const q = s.teamQueued
  if (!q) return
  s.teamQueued = undefined
  later($, 0, async () => {
    // another relay (a reask, a member control, a /relay) may have taken the idle state between the return and this timer: keep the
    // command for that relay's own return to idle, unless a newer one has been queued since
    // a /clear (another conversation) between the typing and now drops it: it was the person's command for that conversation
    const here = await $.session.id().catch(() => undefined)
    if (!here || !q.sid || here !== q.sid) {
      log($, 'queued /team dropped: the session moved on')
      return
    }
    if (s.state !== 'idle') {
      if (!s.teamQueued) s.teamQueued = q
      return
    }
    const text = await performTeam($, q.parsed, q.rawArgs, true, q.sid)
    if (text === TEAM_BUSY) {
      if (!s.teamQueued) s.teamQueued = q
      return
    }
    try { $.ui.toast(text) } catch {}
  })
}

async function relayNow($) {
  if (s.state === 'awaiting' && s.pending) return approveOpenCard($) // a card is open: the person's /relay answers it (RT-1c)
  if (s.state !== 'idle') return { text: RELAY_BUSY }
  if (!hasCSPRNG()) return { text: 'Purdex 接力無法啟動：這個環境沒有 crypto.getRandomValues' }
  // Taken before any await, so a second /relay or a turn's threshold check meanwhile sees
  // `beginning`; a preflight that fails gives it back, if it is still this attempt's.
  disarmIdle()
  s.state = 'beginning'
  const gen = s.gen
  const begun = deferred() // a prompt that arrives while begin is out waits on it (P5b-3)
  s.begun = begun
  const giveBack = () => {
    begun.resolve(undefined)
    if (s.gen === gen && s.state === 'beginning') toIdle($)
  }
  let u, sid
  try {
    u = (await $.session.usage()).context
    sid = await $.session.id()
  } catch (err) {
    giveBack()
    return { text: RELAY_NO_USAGE }
  }
  if (!u || u.percent === undefined) {
    giveBack()
    return { text: RELAY_NO_USAGE }
  }
  // The person's own /relay (RT-1a): the daemon minted a one-use token for exactly this command; with it the relay is direct.
  const token = await personToken($, sid, 'relay')
  if (s.gen !== gen || s.state !== 'beginning' || s.begun !== begun) {
    // a /clear, a compaction or a session start took the attempt while the engine was read
    begun.resolve(undefined)
    return { text: RELAY_NOT_STARTED }
  }
  if (!token) {
    giveBack()
    return { text: RELAY_NO_TOKEN }
  }
  const out = await begin($, sid, gen, u, begun.resolve, true, false, '', token).finally(() => begun.resolve(undefined))
  switch (out.kind) {
    case 'opened': return { text: '已送出接力申請（context ' + u.percent + '%），等待核准' }
    case 'unreachable': return { text: RELAY_UNREACHABLE }
    case 'abandoned': return { text: RELAY_NOT_STARTED }
    case 'failed': return { text: 'pdx relay begin 失敗：' + (out.detail || '(無訊息)') }
    default:
      if (out.code === 'member_relay_is_leads') return { text: RELAY_MEMBER }
      if (out.code === 'self_relay_off') return { text: RELAY_HOST_OFF }
      if (out.code === 'self_relay_paused') return { text: RELAY_PAUSED }
      if (out.code === 'paused_no_quota') return { text: RELAY_QUOTA_PAUSED }
      if (out.code === 'relay_open') return { text: RELAY_BUSY }
      return { text: 'pdx relay begin 被拒：' + (out.code || '(無代碼)') }
  }
}

// approveOpenCard is the person's /relay while a relay card of this session is open (a threshold, idle or re-ask card): their
// own command is the answer. The daemon approves the card (the same request, answered `approved`) and the wait loop already
// running takes it from there; the mod only asks. A card that closed in the meantime would make the daemon open a relay of its
// own that this mod does not hold: that one is cancelled at once and the person is told to type /relay again.
async function approveOpenCard($) {
  const p = s.pending
  const gen = s.gen
  let u, sid
  try {
    u = (await $.session.usage()).context
    sid = await $.session.id()
  } catch {
    return { text: RELAY_NO_USAGE }
  }
  if (!u || u.percent === undefined) return { text: RELAY_NO_USAGE }
  const token = await personToken($, sid, 'relay')
  if (s.gen !== gen || s.state !== 'awaiting' || s.pending !== p) return { text: RELAY_BUSY }
  if (!token) return { text: RELAY_NO_TOKEN }
  const r = await pdx($, ['relay', 'begin', '--self', '--session', sid, '--used', String(u.percent), '--window', String(u.window), '--manual', '--person', token], SELF_TIMEOUT_MS)
  if (r.exitCode === 20 || r.exitCode === 21) return { text: RELAY_UNREACHABLE }
  if (r.exitCode === 13) {
    const code = stderrCode(r)
    if (code === 'relay_open') return { text: RELAY_BUSY }
    return { text: 'pdx relay begin 被拒：' + (code || '(無代碼)') }
  }
  const body = r.exitCode === 0 ? parseJSON(r.stdout) : undefined
  if (!body || !body.op || !body.op.id) return { text: 'pdx relay begin 失敗：' + ((r.stderr || '').trim() || '(無訊息)') }
  if (s.pending !== p || body.request_id !== p.requestId) {
    // not the card this mod holds: a relay it knows nothing of
    report($, body.op.id, 'cancelled', ['--error', 'abandoned'])
    return { text: RELAY_CARD_GONE }
  }
  return { text: RELAY_CARD_APPROVED }
}

// waitAnswer reads one `pdx relay wait`. P5a-2c's shape: exit 0 + Approval
// JSON, state 'approved' or 'open' (the call's --wait bound ran out: call
// again). Anything else at exit 0 — empty or unparsable stdout, an unknown
// state — is NOT an approval: never start the write turn on it (§8.7 (d));
// 10 / 11 / 12 close the request; 20, 21, 1 (a rejected call reads as 20)
// are 'unavailable', treated as not approved.
function waitAnswer(r) {
  if (r.exitCode === 0) {
    const a = parseJSON(r.stdout)
    if (a && a.state === 'open') return 'open'
    if (a && a.state === 'approved') return 'approved'
    return 'unavailable'
  }
  if (r.exitCode === 10) return 'denied'
  if (r.exitCode === 11) return 'timeout'
  if (r.exitCode === 12) return 'cancelled'
  return 'unavailable'
}

const TICK = Symbol('tick')

// sleepUntil waits, inside the prompt.submit hook, for `target` — a promise
// the timers settle (begin's answer, the request's answer) — at most `ms`.
// It races the target with a local `/bin/sleep 5` of the hook's own, again
// while the target is out: a `$` call in flight stops the hook's 10 s budget
// (HookBudget), where an await of the timers' promise alone would let it run
// out and the engine release the prompt early; and a sleep asks the daemon
// nothing (P5b-3 critic: a `pdx relay wait` of the hold's own was one more
// long poll, and lease renewal, per held prompt). Resolves { value } once the
// target settles; undefined when `ms` ran out, a sleep could not run (the
// call rejected, or the sleep failed and would come back at once, again and
// again: the hold fails open, it never spins) or the prompt was abandoned.
async function sleepUntil($, target, ms, signal) {
  const settled = target.then((value) => ({ value }))
  const abandoned = new Promise((resolve) => {
    if (!signal) return // nothing abandons it
    if (signal.aborted) return resolve(undefined)
    signal.addEventListener('abort', () => resolve(undefined), { once: true })
  })
  const deadline = (await $.clock.now()) + ms
  for (;;) {
    const tick = $.process.run(HOLD_SLEEP, { timeoutMs: HOLD_SLEEP_TIMEOUT_MS }).then((r) => (r.exitCode === 0 ? TICK : undefined), () => undefined)
    const r = await Promise.race([settled, abandoned, tick])
    if (r !== TICK) return r
    if ((await $.clock.now()) >= deadline) return undefined
  }
}

// waitLoop is the one long-poll loop per request, its promise kept on the
// request (a loop left over from a request the user's own /clear dropped
// never answers for the next one). It runs in a timer's own dispatch, so a
// held prompt that is abandoned (Esc) never kills it; it settles the
// request's answer, which the held prompts await.
function waitLoop($) {
  const p = s.pending
  if (p.wait) return p.wait
  p.wait = (async () => {
    if (!p.half) $.ui.toast(TOAST_WAITING) // once per request (one loop per request); a half waits for no one
    for (;;) {
      // Until the daemon says the card went unanswered the call carries --return-unanswered, which makes the CLI come back at the
      // mark; after it, the loop goes on as before until the card closes (an approval, a denial, a compaction).
      const argv = ['relay', 'wait', p.requestId]
      if (!p.unanswered) argv.push('--return-unanswered')
      const r = await pdx($, argv, WAIT_TIMEOUT_MS)
      const outcome = waitAnswer(r)
      if (outcome === 'open' && !p.unanswered && unansweredRow(r)) markUnanswered($, p)
      if (outcome === 'unavailable' && p.unanswered) {
        // the card is still open at the daemon (a person can approve it any time): a failed poll is not its end. Keep it, try again later
        // (codex attack); only an answer of the daemon's own leaves the card
        if (s.pending !== p) return 'cancelled'
        await new Promise((resolve) => $.clock.after(UNANSWERED_RETRY_MS, resolve))
        if (s.pending !== p) return 'cancelled'
        continue
      }
      if (outcome !== 'open') return outcome
    }
  })().catch(() => 'unavailable').then((outcome) => {
    p.answer.resolve(outcome) // the held prompts go on after settle below has moved the state
    settle($, p, outcome)
    return outcome
  })
  return p.wait
}

// unansweredRow says whether a `pdx relay wait` answer is an open card that the daemon left unanswered (RT-2a1).
function unansweredRow(r) {
  if (r.exitCode !== 0) return false
  const a = parseJSON(r.stdout)
  return !!a && a.state === 'open' && typeof a.unanswered_at === 'number' && a.unanswered_at > 0
}

// markUnanswered is the mod's side of a final card nobody answered: the session is paused by the daemon, so the prompts held on
// the card go on at once and unchanged (the hold's answer is 'unanswered', not 'approved'), later prompts are not held, and the
// status line says what the person has to do. The card stays open; an approval later runs the ordinary settle.
function markUnanswered($, p) {
  p.unanswered = true
  if (s.pending !== p || s.state !== 'awaiting') return
  $.ui.status(STATUS_UNANSWERED)
  p.answer.resolve('unanswered')
}

function settle($, p, outcome) {
  // A request the mod let go answers for nothing (its held prompts went on
  // at letGo, and whatever let it go cleared the status line or another
  // request owns it now).
  if (s.pending !== p) return
  $.ui.status(undefined)
  if (s.state !== 'awaiting') return
  if (outcome !== 'approved') {
    toIdle($) // an idle ask's answer no longer counts against the threshold's +10 guard (RT-2c T26)
    if (outcome === 'timeout' && p.idle && !p.half) halfLater($) // the idle card ran out: write the half now (RT-3b T35)
    return
  }
  s.state = 'approved'
  if (p.reused) return reuseWritten($, p)
  startWrite($, p)
}

// startWrite is the step after an approval — a self relay's (settle) or a claimed member relay's (claim): the
// write prompt, composed at use, from a timer. The state is already 'approved'.
function startWrite($, p) {
  later($, STEP_MS, async () => {
    // all bounded (10 s, 8 s) and asked together: the step waits no longer than whoami did
    const [who, body, git, team] = await Promise.all([whoami($), bodyFor($, 'write'), gitFacts($), teamFacts($, p)])
    p.who = who
    p.git = git
    p.team = team
    if (s.pending !== p || s.state !== 'approved') return // the await may span the user's /clear
    // The relay lock goes up BEFORE the write prompt is submitted, not in the write turn's turn.start: the real engine
    // does not wait for a turn.start hook's await, so the model's first tool call can run before a lock raised there
    // (measured, docs/testing/member-relay-acceptance.md). Fix rounds do not lock again.
    if (!p.lockTried) {
      // A user turn that is running (or starts while the lock call is out) must not run under the lock: the write
      // waits for its turn.complete, as the claim does (turn.complete restarts this step, which then locks afresh).
      if (s.turnRunning) { s.writeDeferred = p; return }
      p.lockTried = true
      await lockRelay($, p)
      if (s.pending !== p || s.state !== 'approved') {
        await unlockRelay($, p) // the relay ended while the call was out: nothing else will lower it
        return
      }
      if (s.turnRunning) {
        await unlockRelay($, p)
        p.lockTried = false
        if (s.pending !== p || s.state !== 'approved') return
        // that turn may have ended while the unlock was out (its turn.complete found nothing deferred): go on at once
        if (s.turnRunning) s.writeDeferred = p
        else startWrite($, p)
        return
      }
    }
    arm(p, 'approved')
    try {
      await submit($, compose('write', body, p))
    } catch (err) {
      giveUp($, p, 'approved', 'failed', 'handoff_incomplete', 'write prompt: ' + String(err))
      return
    }
    report($, p.op.id, 'writing')
  })
}

// teamFacts is the write prompt's `{{team}}` (§8.2 step 4): a member's lead (from its claim), a lead's roster
// (`pdx team --json`), nothing for anyone else. Called from the step's timer, never inside a hook.
async function teamFacts($, p) {
  if (p.lead) return leadLine(p.lead, cleanGit)
  if (s.role !== 'lead') return ''
  const r = await pdx($, ['team', '--json'], PROMPTS_TIMEOUT_MS)
  return rosterLines(r.exitCode === 0 ? parseJSON(r.stdout) : undefined, cleanGit)
}

// ---- member relay (P6-6): the control message, the claim ----

// claim takes the op the newest control message named, from a timer, when nothing else is going on; it checks
// again here, since the state may have moved since it was scheduled. A claim that fails does nothing: the
// daemon's timeout reports it.
async function claim($, gen) {
  if (s.turnRunning || s.state !== 'idle' || s.gen !== gen) return // turn.complete, an idle return or the next control asks again
  const sid = await $.session.id()
  // Only ops the daemon accepted as `seen` are kept; more than one is a re-send or a newer op: tried oldest first.
  let body, op
  while (s.control.length > 0) {
    const opId = s.control.shift()
    const r = await pdx($, ['relay', 'claim', opId, '--session', sid], CALL_TIMEOUT_MS)
    if (r.exitCode !== 0) {
      log($, 'relay claim ' + opId + ' not taken (exit ' + r.exitCode + '): ' + String(r.stderr || '').trim().split('\n')[0])
    } else {
      body = parseJSON(r.stdout)
      op = claimOp(body)
      if (op) break
      log($, 'relay claim ' + opId + ': the answer is not a claim')
    }
    if (s.turnRunning || s.state !== 'idle' || s.gen !== gen) return // the state moved while the claim was out
  }
  if (!op) return
  s.control = [] // the rest named ops that are not this member's, or the same one again
  const u = (await $.session.usage()).context
  if (s.gen !== gen || s.state !== 'idle' || s.pending) return log($, 'relay claim ' + op.id + ' taken, but the session moved on; the daemon times it out')
  const answer = deferred()
  answer.resolve('approved')
  const p = {
    cause: 'lead',
    op, requestId: undefined, path: op.handoff_path, oldSession: sid, oldRef: op.ref, before: usageLine(u),
    nonce: undefined, nonceState: undefined, who: '', lead: body.lead && typeof body.lead === 'object' ? body.lead : undefined, answer,
  }
  if (op.mode === 'handoff') p.handoff = true // pdx kill --handoff (RT-3c): written, then the daemon closes the member - no /clear, no half
  s.pending = p
  s.state = 'approved'
  s.fixRounds = 0
  halfSpent($) // a member relay claimed: the daemon deleted the half's row
  // A turn the user started while the claim was out (id, the daemon, usage) is not interrupted: the write
  // waits for its turn.complete (P6-6 R1).
  if (p.handoff && body.reuse === true) return handoffReused($, p)
  if (s.turnRunning) s.writeDeferred = p
  else startWrite($, p)
}

// handoffReused: the daemon says the handoff op's file is the member's fresh handoff. If it still checks out nothing is written: writing
// and written are reported and the member goes idle until the daemon closes it; if not, it is written as any handoff.
function handoffReused($, p) {
  later($, STEP_MS, async () => {
    if (s.pending !== p || s.state !== 'approved') return
    if (!(await checkHandoff($, p)).ok) return s.turnRunning ? (s.writeDeferred = p) : startWrite($, p)
    if (s.pending !== p || s.state !== 'approved') return
    report($, p.op.id, 'writing')
    report($, p.op.id, 'written')
    toIdle($)
  })
}

function claimLater($) {
  const gen = s.gen
  later($, 0, () => claim($, gen))
}

// compactedAfter reports a compaction that really ran, after it did; compactedLater reports a compaction the mod did NOT intercept (P7-2, spec §8.5): from a timer, never awaited, so the
// compaction never waits for it. Whatever the role (coordinator decision 12: the first hello may answer before the member
// row exists), the daemon decides whether the lead is told (a member's auto one only). The session id is read in the timer.
function compactedAfter($, e, result, trigger = e.trigger) {
  // only a compaction that ran: a hook beneath that skipped it (or threw, which never reaches here) reports nothing
  if (!result || result.skip === undefined) compactedLater($, trigger)
  return result
}

// ---- idle relay (spec §4) ----

// disarmIdle drops the armed idle timer, if any. Its fire acts only while it is still s.idleTimer, so a timer the engine
// could not cancel in time (or an await in its handler) finds itself gone.
function disarmIdle() {
  const t = s.idleTimer
  s.idleTimer = undefined
  s.idleWanted = false
  if (t && t.handle && typeof t.handle.cancel === 'function') t.handle.cancel()
}

// armIdle (re)starts the idle timer at the end of a main turn: an ordinary session that is idle, whose hello advertised
// the feature. Re-arming replaces the timer.
function armIdle($) {
  disarmIdle()
  if (!s.helloOK || s.role === 'member' || s.idleMinutes <= 0 || s.state !== 'idle' || s.half) return
  const t = { gen: s.gen, handle: undefined }
  s.idleTimer = t
  t.handle = $.clock.after(s.idleMinutes * 60_000, () => { void idleFire($, t).catch((err) => log($, 'idle ask failed: ' + String(err))) })
}

// idleLive: the cheap part of the gate, asked again after every await of the fire (as maybeBegin does).
const idleLive = (t) => s.idleTimer === t && s.gen === t.gen && s.interactive && s.helloOK && s.role !== 'member' &&
  s.idleMinutes > 0 && s.state === 'idle' && !s.turnRunning && s.control.length === 0 && !s.pausedLatch && !s.half // a fresh half asks nothing more until the conversation moves

// idleFire is the timer's handler (never inside a hook): the maybeBegin gate with the idle threshold and the growth guard,
// and no running background task or session cron (D8). It opens the same self-relay request, with the reason, and takes
// `beginning` with nothing awaited between its last look and that move. The threshold's +10 guard does not apply to it
// and its answer does not feed that guard (RT-2c T26): an idle ask is its own ladder.
async function idleFire($, t) {
  if (!idleLive(t) || !hasCSPRNG()) return
  const u = (await $.session.usage()).context
  if (!idleLive(t)) return
  if (u.percent === undefined || u.percent < s.idleThreshold) return
  if (s.floor !== undefined && (u.tokens ?? 0) < s.floor + s.minGrowth) return
  if (backgroundBusy()) return
  const sid = await $.session.id()
  if (!idleLive(t) || backgroundBusy()) return
  s.idleTimer = undefined
  s.state = 'beginning'
  s.idleAsk = true
  const gen = s.gen
  const begun = deferred() // a prompt that arrives while begin is out waits on it, then withdraws the request it opened
  s.begun = begun
  later($, 0, () => begin($, sid, gen, u, begun.resolve, false, true).finally(() => begun.resolve(undefined)))
}

// withdrawIdle: a prompt arrived while an idle ask is open (D6). toIdle first, so the prompt goes on at once and
// unchanged; then the status line; then the report. The wait loop's late answer for the request is ignored (settle).
function withdrawIdle($, p) {
  if (s.pending !== p || s.state !== 'awaiting') return
  toIdle($)
  $.ui.status(undefined)
  report($, p.op.id, 'cancelled', ['--error', 'resumed'])
}

// ---- the idle half (RT-3b, relay/team rules v2 T35, T36) ----

// halfLive: the gate of a half begin, asked again after every await (as idleLive is): an ordinary idle session whose hello advertised
// the feature, with nothing running and no half already.
const halfLive = (gen) => s.gen === gen && s.interactive && s.helloOK && s.role !== 'member' && s.state === 'idle' && !s.turnRunning &&
  s.control.length === 0 && !s.pausedLatch && !s.half && s.idleMinutes > 0

// halfLater: an idle card settled `timeout`. From a timer, the mod asks the daemon for a half - the handoff file written, nothing
// cleared - which the daemon claims at once. It holds no prompt (it takes neither idleAsk nor the hold) and asks for no one.
function halfLater($) {
  const gen = s.gen
  later($, 0, async () => {
    if (!halfLive(gen) || !hasCSPRNG()) return
    const u = (await $.session.usage().catch(() => undefined))?.context
    const sid = await $.session.id().catch(() => undefined)
    if (!u || u.percent === undefined || !sid || !halfLive(gen) || backgroundBusy()) return
    s.state = 'beginning'
    s.halfBeginning = true
    const begun = deferred()
    s.begun = begun
    await begin($, sid, gen, u, begun.resolve, false, true, '', '', true).finally(() => {
      if (s.gen === gen) s.halfBeginning = false
      begun.resolve(undefined)
    })
  })
}

// reuseWritten: the daemon opened this relay on the fresh half's file, which still checks out, so there is nothing to write: writing and
// written are reported and the relay goes on to /clear. A file that stopped checking out is written again as an ordinary relay.
function reuseWritten($, p) {
  later($, STEP_MS, async () => {
    p.who = await whoami($)
    if (s.pending !== p || s.state !== 'approved') return
    const c = await checkHandoff($, p)
    if (s.pending !== p || s.state !== 'approved') return
    if (!c.ok) {
      s.half = undefined
      startWrite($, p) // the same path, written over
      return
    }
    halfSpent($) // the claim spends it
    report($, p.op.id, 'writing')
    report($, p.op.id, 'written')
    s.state = 'clearing'
    startClear($, p)
  })
}

// halfSpent: a relay claimed (the daemon deleted the half's row at the claim), so the mod forgets the half without telling anyone, and
// the status line stops promising a file.
function halfSpent($) {
  s.half = undefined
  if (s.halfStatus) { s.halfStatus = false; $.ui.status(undefined) }
}

// dropHalf forgets the fresh half: the conversation moved on, so its file no longer says where it is. `stale` also tells the daemon
// (from a timer, under the session id the half was written in); a compaction does not, the daemon deletes the row at one.
function dropHalf($, stale) {
  const h = s.half
  if (!h) return
  s.half = undefined
  if (s.halfStatus) { s.halfStatus = false; $.ui.status(undefined) } // the status line no longer promises a file
  if (!stale) return
  later($, 0, async () => {
    const r = await pdx($, ['relay', 'fresh', '--session', h.sid, '--op', h.op, '--stale'], CALL_TIMEOUT_MS)
    if (r.exitCode !== 0) log($, 'relay fresh --stale failed (exit ' + r.exitCode + ')')
  })
}

// interceptedLater tells the daemon, from a timer, that the member's idle compaction was stopped (RT-4 T42).
function interceptedLater($) {
  const since = s.lastTurnDoneAt
  const gen = s.gen
  later($, 0, async () => {
    const sid = await $.session.id()
    const argv = ['relay', 'compacted', '--session', sid, '--trigger', 'idle', '--intercepted']
    if (since > 0) argv.push('--period', String(since)) // names this idle period for the daemon: one decision per period
    const r = await pdx($, argv, CALL_TIMEOUT_MS)
    // The daemon decides by its own, authoritative role. `silent`: it does not know this session as a member (released, or the role is
    // stale): this idle compaction was stopped for nothing, so the role is dropped and hello says what it is now; the next one runs.
    const body = r.exitCode === 0 ? parseJSON(r.stdout) : undefined
    if (body && body.route === 'silent' && s.gen === gen && s.role === 'member') {
      s.role = 'none'
      helloLater($)
    }
  })
}

function compactedLater($, trigger) {
  if (trigger !== 'auto' && trigger !== 'manual' && trigger !== 'idle') return
  later($, 0, async () => {
    const sid = await $.session.id()
    await pdx($, ['relay', 'compacted', '--session', sid, '--trigger', trigger], CALL_TIMEOUT_MS)
  })
}

// submit sends a prompt of the mod's; a prompt that did not enter — the
// call rejected, or a hook beneath dropped it — throws, since no turn of it
// will ever start.
async function submit($, text) {
  const r = await $.prompt.submit({ text })
  if (r && r.drop !== undefined) throw new Error('prompt dropped: ' + r.drop)
}

// giveUp ends a relay whose step, deferred to a timer, failed: when the
// same request is still in the state the step was taken in, it reports and
// goes back to idle (asked again at +10 points), rather than leaving the
// mod waiting for a turn or a /clear that will never come. False when the
// relay had moved on meanwhile (nothing is reported then).
function giveUp($, p, inState, state, error, why) {
  log($, why)
  if (s.pending !== p || s.state !== inState) return false
  toIdle($)
  report($, p.op.id, state, ['--error', error])
  return true
}

async function checkHandoff($, p) {
  const text = await $.fs.read(p.path).catch(() => '')
  const missing = REQUIRED.filter((h) => !text.includes(h))
  return { ok: text.length > 200 && missing.length === 0, missing }
}

// startClear is the step after the handoff file passed its check: the lock down, then the mod's own /clear, from a timer.
// The write turn's end takes it, and so does a mod that reloaded after `written` (recover).
function startClear($, p) {
  later($, STEP_MS, async () => {
    if (s.pending !== p || s.state !== 'clearing') return
    await unlockRelay($, p) // before the /clear, so the new conversation never starts under the lock
    if (s.pending !== p || s.state !== 'clearing') return
    try {
      await $.command.run({ command: 'clear' })
    } catch (err) {
      giveUp($, p, 'clearing', 'cancelled', 'abandoned', '/clear: ' + String(err)) // written → cancelled
    }
  })
}

// ---- a final card the daemon left unanswered, picked up again by a mod that reloaded (RT-2a1 T17, RT-2c T27) ----
// hello's `waiting` names the session's open card whose deadline passed unanswered. A mod that holds no request has lost it with
// its memory: it takes the card as its own again - awaiting, unanswered, the wait loop running - so an approval in the App still
// starts the write, and a compaction still cancels it.
function adoptWaitingLater($, w, sid) {
  if (!w.request_id || !w.op || typeof w.op !== 'object' || typeof w.op.id !== 'string' || w.op.id === '') return
  const gen = s.gen
  later($, 0, async () => {
    if (s.pending || s.state !== 'idle' || s.gen !== gen) return
    const u = (await $.session.usage().catch(() => undefined))?.context
    const now = await $.session.id().catch(() => undefined)
    if (s.pending || s.state !== 'idle' || s.gen !== gen || now !== sid) return // the conversation moved on while the engine was read
    const answer = deferred()
    answer.resolve('unanswered')
    const p = {
      idle: false, idlePct: u?.percent, cause: 'threshold',
      op: w.op, requestId: w.request_id, path: w.op.handoff_path, oldSession: sid, oldRef: w.op.ref, before: u ? usageLine(u) : '',
      nonce: undefined, nonceState: undefined, who: '', answer, unanswered: true,
    }
    disarmIdle()
    s.pending = p
    s.state = 'awaiting'
    s.fixRounds = 0
    s.lastAskPct = Math.max(s.lastAskPct ?? 0, LAST_ASK_PCT) // a final card is by definition the last ask: the reload must not forget it (codex)
    $.ui.status(STATUS_UNANSWERED)
    await waitLoop($)
  })
}

// ---- a mod that reloaded in the middle of a relay (#2441) ----
// `pdx setup` rewrites the mod folder and the mod reloads with an empty memory: the relay it was running has no
// state here, and nothing would /clear. hello's answer names the session's open op (claimed / writing / written;
// earlier states have their own paths, and a daemon without the field changes nothing). `written`: the handoff file
// is on disk, so go on as the write turn's end would (check, lock down, /clear, then cleared and the seed). `claimed`
// / `writing`: the write was under way and its prompt, nonce and git facts died with the old mod; re-sending it could
// double a prompt the model is already answering, so the op is failed with a reason the lead can read
// (`mod_reloaded`) and the lead relays again.
const recovered = new Set() // op ids this mod instance took over (or ended): a hello that still carries the op does not run it again
const recovering = new Set() // op ids with a recovery scheduled or running: one at a time
let waitingRecovery // { active, sid }: a recovery that found the conversation busy (a turn running, the state taken): the next turn.complete runs it again

function recoverLater($, active, sid) {
  const op = active.op
  if (!op || typeof op !== 'object' || typeof op.id !== 'string' || op.id === '' || recovered.has(op.id) || recovering.has(op.id)) return
  if (op.state !== 'written' && op.state !== 'claimed' && op.state !== 'writing') return
  recovering.add(op.id)
  later($, 0, async () => {
    let busy = false
    try {
      busy = (await recover($, active, sid)) === 'retry'
    } finally {
      recovering.delete(op.id)
    }
    if (busy) waitingRecovery = { active, sid }
  })
}

// resumeRecovery runs a recovery that waited for the conversation to be free (turn.complete is where it is). True when it ran.
function resumeRecovery($) {
  const w = waitingRecovery
  if (!w) return false
  waitingRecovery = undefined
  recoverLater($, w.active, w.sid)
  return true
}

// recoverFail ends the op the old mod left: its relay lock down first (fail-open, as at every other end), then the
// terminal report (a report that does not land is re-sent at the next turn end, as any other).
async function recoverFail($, op, sid, reason, why) {
  recovered.add(op.id)
  log($, 'relay ' + op.id + ' ' + why)
  await unlockRelay($, { op, oldSession: sid, locked: true })
  report($, op.id, 'failed', ['--error', reason])
}

// recover answers 'retry' when the conversation is busy with something else right now (a turn, the state taken) and the
// op is still waiting for its owner, 'done' when it took the op over or ended it, 'gone' when the session moved on (the
// op is not that conversation's to finish any more).
async function recover($, active, sid) {
  const op = active.op
  const sameSession = async () => (await $.session.id().catch(() => undefined)) === sid
  // what must be true to act: nothing of the relay in this mod, and (for the /clear) no turn running
  const verdict = async (needsNoTurn) => {
    if (!(await sameSession())) return 'gone'
    if (s.pending && s.pending.op.id === op.id) return 'gone' // the member claim path took this very op: it owns it
    if (s.state !== 'idle' || s.pending || (needsNoTurn && s.turnRunning)) return 'retry'
    return 'ok'
  }
  let v = await verdict(op.state === 'written')
  if (v !== 'ok') return v === 'retry' ? 'retry' : 'gone'
  if (op.state !== 'written') {
    await recoverFail($, op, sid, RELAY_MOD_RELOADED, 'was ' + op.state + ' when the mod reloaded: reported failed (mod_reloaded)')
    return 'done'
  }
  const p = {
    cause: 'recovered',
    op, requestId: op.request_id || undefined, path: op.handoff_path, oldSession: sid, oldRef: op.ref, before: '',
    nonce: undefined, nonceState: undefined, who: '', // the seed names neither the lead nor the team (the write prompt did): only the old ref, the path and the tasks
    answer: deferred(), locked: true, // the old mod may have left the relay lock up: unlockRelay lowers it (fail-open) before the /clear
  }
  p.answer.resolve('approved')
  const c = await checkHandoff($, p)
  if (!c.ok) {
    v = await verdict(false)
    if (v !== 'ok') return v === 'retry' ? 'retry' : 'gone'
    await recoverFail($, op, sid, 'handoff_incomplete', 'was written when the mod reloaded but its file is not complete: reported failed')
    return 'done'
  }
  const u = (await $.session.usage().catch(() => undefined))?.context
  p.before = u ? usageLine(u) : ''
  p.who = await whoami($)
  v = await verdict(true) // everything above was awaited: look again before /clear
  if (v !== 'ok') return v === 'retry' ? 'retry' : 'gone'
  recovered.add(op.id)
  log($, 'relay ' + op.id + ' was written when the mod reloaded: going on to /clear and the seed')
  s.pending = p
  s.state = 'clearing'
  startClear($, p)
  return 'done'
}

async function onWriteTurnDone($) {
  const p = s.pending
  s.writeTurnId = undefined // checked once
  const c = await checkHandoff($, p)
  if (s.pending !== p) return
  if (c.ok && p.handoff) {
    // A handoff ends where its file is written (RT-3c T39): the daemon closes the member. No /clear, no seed, no half, no status or
    // toast, no threshold check.
    report($, p.op.id, 'written')
    toIdle($)
    return
  }
  if (c.ok && p.half) {
    // A half ends where its file is written: no /clear, no seed (RT-3b T35). The session is idle again and keeps the half for the next
    // relay; the threshold check runs once now, so at >= the threshold it asks at once and reuses it.
    report($, p.op.id, 'written')
    let at = 0
    try { at = await $.clock.now() } catch {}
    if (s.pending !== p) return // the conversation moved on while the clock was read
    // The half is recorded BEFORE the idle state is exposed: a reask, a control claim or a queued /team that toIdle starts at once
    // must find it (and reuse it), not begin as if there were none (codex R1).
    s.half = { op: p.op.id, path: p.path, at, sid: p.oldSession }
    toIdle($)
    $.ui.status(STATUS_HALF)
    s.halfStatus = true
    $.ui.toast(toastHalf(p.path))
    await maybeBegin($)
    return
  }
  if (c.ok) {
    s.state = 'clearing'
    report($, p.op.id, 'written')
    startClear($, p)
    return
  }
  if (s.fixRounds < MAX_FIX_ROUNDS) {
    s.fixRounds += 1
    later($, STEP_MS, async () => {
      if (s.pending !== p) return
      const body = await bodyFor($, 'fix') // every round asks again (open question 9)
      if (s.pending !== p || s.state !== 'approved') return
      arm(p, 'approved')
      try {
        await submit($, compose('fix', body, p, { missing: c.missing.join('、') || '(內容過短)' }))
      } catch (err) {
        giveUp($, p, 'approved', 'failed', 'handoff_incomplete', 'fix prompt: ' + String(err))
      }
    })
    return
  }
  toIdle($)
  report($, p.op.id, 'failed', ['--error', 'handoff_incomplete'])
  $.ui.toast(TOAST_GAVE_UP)
}

async function onSeedTurnDone($) {
  const p = s.pending
  const u = (await $.session.usage()).context
  if (s.pending !== p) return
  report($, p.op.id, 'done')
  toIdle($)
  s.floor = u.tokens // the loop guard: the next ask needs minGrowth more (§8.1)
  s.lastAskPct = undefined
}

export function register(on) {
  registerAsk(on) // tool.call{AskUserQuestion} only: no event this module hooks below
  // The event reporter (interface U1 spec §6.5): unmatched on events this module does not
  // hook, matched on the ones it does; registered first, so its hooks wrap the relay's.
  registerEvents(on)
  registerGate(on) // tool.call{Bash} only: host load control for the calls the PATH shims cannot see

  // The member-relay control message (P6-6, M1): consumed whatever the state (codex finding 1), so the model never
  // sees it. The daemon is told the mod has it now (Q2 branch A); the claim waits for the running turn.
  on('session.receive', async ($, e, next) => {
    if (!s.interactive) return next(e)
    const reaskId = controlReask(e)
    if (reaskId) {
      takeReask($, reaskId)
      return { consumed: CONSUMED_REASK }
    }
    const opId = controlOp(e)
    if (!opId) return next(e)
    if (!(s.pending && s.pending.op.id === opId)) {
      // Branch A: the daemon learns the mod has the message now, not at the claim. Its answer is also the proof the
      // op is this member's (any peer can send the marker; `seen` is refused for an op that is not): only an op
      // that was seen is kept for the claim.
      later($, 0, async () => {
        const sid = await $.session.id()
        const r = await pdx($, ['relay', 'seen', opId, '--session', sid], CALL_TIMEOUT_MS)
        // s.gen moves at every return to idle, so the conversation is told by its session id (a /clear changes it)
        if (r.exitCode !== 0 || (await $.session.id().catch(() => undefined)) !== sid) return log($, 'relay control ' + opId + ' dropped (seen exit ' + r.exitCode + ')')
        if (!s.control.includes(opId)) s.control = [...s.control, opId].slice(-MAX_CONTROLS)
        if (!s.turnRunning && s.state === 'idle') claimLater($)
      })
    }
    return { consumed: CONSUMED }
  })

  on('session.start', async ($, e, next) => {
    const stale = s.pending
    if (stale && stale.locked) later($, 0, () => unlockRelay($, stale)) // the reset forgets the relay: lower its lock first
    resetState()
    s.interactive = !!e.isInteractive
    if (!s.interactive) return next(e) // a Nexen worker's `claude -p`: the mod does nothing (spec §5)
    const t = Number(await $.env.get('PDX_RELAY_THRESHOLD').catch(() => undefined))
    if (t > 0 && t <= 100) { s.threshold = t; s.envThreshold = true }
    // Idle relay (D9): read now, used only when hello advertises the feature.
    const im = Number(await $.env.get('PDX_RELAY_IDLE_MINUTES').catch(() => undefined))
    if (Number.isInteger(im) && im >= 1 && im <= IDLE_MINUTES_MAX) s.envIdleMinutes = im
    const it = Number(await $.env.get('PDX_RELAY_IDLE_THRESHOLD').catch(() => undefined))
    if (Number.isInteger(it) && it >= 1 && it <= 100) s.envIdleThreshold = it
    const cfg = parseJSON(await $.fs.read($.plugin.root + '/pdx.json').catch(() => ''))
    if (cfg && cfg.pdx) s.pdx = cfg.pdx // written beside VERSION by the extractor; absent in `claude plugin test`
    s.config = cfg && typeof cfg.config === 'string' ? cfg.config : ''
    await $.command.register({ name: 'relay', description: 'Purdex 自我接力：now 立刻接力（不帶參數＝now）、off 暫停、on 恢復、status 查看', argumentHint: 'now|off|on|status（不帶＝now）' })
      .catch((err) => log($, '/relay not registered: ' + String(err)))
    await $.command.register({ name: 'team', description: 'Purdex team：不帶＝成為 lead／看 team；spawn、adopt、release、kill', argumentHint: '[名稱或說明] | spawn <任務> [--model m] [--effort e] | adopt <ref> | release <ref> | kill <ref>' })
      .catch((err) => log($, '/team not registered: ' + String(err)))
    await $.command.register({ name: 'lead', description: 'Purdex：請這個 session 申請成為 lead（將移除，請改用 /team）', argumentHint: '[名稱／短名等補充]' })
      .catch((err) => log($, '/lead not registered: ' + String(err)))
    helloLater($)
    return next(e)
  })

  // Own-turn recognition (MP3): a plugin's own prompt.submit hook never sees
  // its own $.prompt.submit, so the write / fix / seed turn is told at
  // turn.start by the nonce minted for that prompt (arm), and acted on at the
  // turn.complete carrying that turnId. The nonce is accepted only in the
  // state it was minted for and only once: the turnId is sealed, and a later
  // turn carrying the same text (an echo, a paste, another plugin) is not
  // the relay's.
  on('turn.start', async ($, e, next) => {
    const p = s.pending
    let own = false // the mod's own write / seed turn
    if (s.interactive && !e.agentId) { s.turnRunning = true; s.mainTurns++; disarmIdle() }
    if (s.interactive && s.leadAsk && s.leadAsk.turnId === undefined && typeof e.text === 'string' && e.text.includes(s.leadAsk.nonce)) s.leadAsk.turnId = e.turnId
    if (s.interactive && p && p.nonce && s.state === p.nonceState && typeof e.text === 'string' && e.text.includes(p.nonce)) {
      const writing = s.state === 'approved'
      if (writing) s.writeTurnId = e.turnId
      else s.seedTurnId = e.turnId
      p.nonce = undefined
      own = true
    }
    if (s.interactive && !e.agentId && s.half && !own) dropHalf($, true) // the conversation moved on: the half's file is stale (RT-3b T36)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    let r
    try {
      r = await next(e)
    } finally {
      if (s.interactive && !e.agentId) s.turnRunning = false // a hook beneath that throws must not leave the turn running for good
      if (s.interactive && !e.agentId) { try { s.lastTurnDoneAt = await $.clock.now() } catch {} }
    }
    if (!s.interactive || e.agentId) return r
    if (s.leadAsk && s.leadAsk.turnId !== undefined && e.turnId === s.leadAsk.turnId) s.leadAsk = undefined // the /lead turn has ended: it may be asked again
    try {
      if (s.writeDeferred) {
        const d = s.writeDeferred
        s.writeDeferred = undefined
        if (s.pending === d && s.state === 'approved') startWrite($, d)
      }
      if (s.control.length > 0 && s.state === 'idle') claimLater($) // a member-relay control that waited for this turn (P6-6)
      if (!s.helloOK && !s.helloBusy) helloLater($) // the last hello failed (daemon down): say it again
      if (s.outbox.length) { s.held.clear(); pump($) } // re-send what did not land (§8.3)
      if (s.pending && s.writeTurnId !== undefined && e.turnId === s.writeTurnId) await onWriteTurnDone($)
      else if (s.pending && s.seedTurnId !== undefined && e.turnId === s.seedTurnId) await onSeedTurnDone($)
      else if (resumeRecovery($)) { /* the relay a reload left is finished first: no new ask this turn */ }
      else if (s.state === 'idle' && s.reaskPending) drainReask($) // a reask that waited for this turn to end (UP-4)
      else if (s.state === 'idle') await maybeBegin($)
      if (s.state === 'idle') { // idle relay: the stretch of idleness starts at the end of a main turn
        armIdle($)
        if (!s.helloOK) s.idleWanted = true // hello has not answered yet: its answer arms the timer
      }
    } catch (err) {
      log($, 'turn.complete failed: ' + String(err))
    }
    return r
  })

  // /clear gives the conversation a new session id (M1). The mod's own
  // /clear (state clearing) reports cleared under it and seeds the new
  // conversation; any /clear says hello again under it (P5b-1: the daemon
  // keys mod presence by session id). Startup / resume are session.start's.
  on('classic.SessionStart', async ($, e, next) => {
    const r = await next(e)
    if (!s.interactive || e.source !== 'clear') return r
    const p = s.pending
    disarmIdle()
    s.gen += 1 // a new session id: no begin sent under the old one answers for it
    s.control = [] // a control message named the old session id: it is the old conversation's
    s.helloOK = false // nor does the old session's hello: the new one is sent below
    if (s.state === 'clearing' && p) {
      halfSpent($) // the mod's own /clear: the relay spent the half (the daemon deleted its row at the claim)
      s.state = 'seeding'
      report($, p.op.id, 'cleared', ['--new-session', await $.session.id()])
      helloLater($)
      later($, STEP_MS, async () => {
        if (s.pending !== p) return
        // The new conversation is idle while the body is asked for (≤ 8 s;
        // M29 with the daemon up): a prompt typed meanwhile runs first.
        const [body, tasks] = await Promise.all([bodyFor($, 'seed'), tasksFor($)])
        if (s.pending !== p || s.state !== 'seeding') return // the user's own /clear meanwhile
        arm(p, 'seeding')
        try {
          await submit($, compose('seed', body, p, { tasks }))
        } catch (err) {
          if (!giveUp($, p, 'seeding', 'failed', 'handoff_incomplete', 'seed prompt: ' + String(err))) return
          // the /clear did happen: this is a new conversation, asked afresh
          s.floor = undefined
          s.lastAskPct = undefined
          $.ui.toast(toastSeedFailed(p.path))
        }
      })
      return r
    }
    // The user's own /clear: start over (the floor and the +10 re-ask were the
    // old conversation's). A relay in flight is ended at the daemon first, so
    // no dialog or op waits on a mod that moved on: awaiting / approved →
    // cancelled{abandoned} (the daemon closes the approval row), seeding →
    // failed{handoff_incomplete}; beginning needs nothing here — the
    // generation bump above has begin() cancel the op when it answers.
    // toIdle first: a prompt held on the request goes on before the report.
    const was = s.state
    dropHalf($, true) // the user's own /clear: the half's file is stale (RT-3b T36)
    toIdle($)
    if (p && (was === 'awaiting' || was === 'approved')) report($, p.op.id, 'cancelled', ['--error', 'abandoned'])
    else if (p && was === 'seeding') report($, p.op.id, 'failed', ['--error', 'handoff_incomplete'])
    if (was === 'awaiting') $.ui.status(undefined)
    s.floor = undefined
    s.lastAskPct = undefined
    s.latchEpoch++
    s.pausedLatch = false // a /clear is a new session id, which the daemon never paused: the old conversation's latch and waiting reask are not its
    s.reaskPending = ''
    s.askBusy = undefined // an ask still out was the old conversation's: its answer is dropped (epoch), and it holds nothing here
    s.askEpoch++
    waitingRecovery = undefined // see resetState
    helloLater($)
    return r
  })

  on('tool.check', { tool: 'Write' }, async ($, e, next) => {
    if (s.pending && e.input && e.input.file_path === s.pending.path) return { decision: 'allow', reason: 'Purdex 接力檔' }
    return next(e)
  }).catch(($, e, next) => (next.called ? next(e) : { decision: 'deny', reason: 'pdx-relay guard failed' }))

  on('tool.check', { tool: 'Edit' }, async ($, e, next) => {
    if (s.pending && e.input && e.input.file_path === s.pending.path) return { decision: 'allow', reason: 'Purdex 接力檔' }
    return next(e)
  }).catch(($, e, next) => (next.called ? next(e) : { decision: 'deny', reason: 'pdx-relay guard failed' }))

  // ---- P5b-3: the hold, the compact rule, /relay ----

  // The hold (U7, §8.7 (b)): while a request is open no prompt of the main
  // conversation starts a turn, whatever its origin (the mod's own never
  // reaches this hook, MP3). The hook waits for the answer the timer's loop
  // settles, on local sleeps of its own (sleepUntil): a `$` call in flight,
  // so its 10 s budget stands still however long the request stays open, and
  // the daemon is asked nothing more per held prompt (P5b-3 critic). A
  // prompt that arrives while begin is still out waits for begin's answer
  // (≤ BEGIN_HOLD_MS) and goes on unchanged when begin opened nothing; the
  // request's answer is waited for ≤ HOLD_MAX_MS. Every prompt is held, however
  // many: a cap that let one through would start a turn while the request is
  // open (U7, spec §8.7 (b)); each costs a local sleep, not the daemon. Approved ⇒
  // NOTE after the existing context; anything else ⇒ unchanged. The status
  // line, the toast and the loop are the timer's, so Esc here ends this
  // prompt only. The hold never loses a prompt: whatever fails, its .catch
  // answers next(e) (fail-open; P5b-3 review).
  on('prompt.submit', async ($, e, next) => {
    if (!s.interactive) return next(e)
    disarmIdle() // a prompt ends the idle stretch, whatever becomes of it
    // An idle ask holds nothing (D6): the prompt withdraws it and goes on unchanged. While begin is still out it waits for
    // begin's answer (as a held prompt does, ≤ BEGIN_HOLD_MS); begin withdraws the op it opens (idleWithdraw).
    if (s.idleAsk && s.state === 'beginning' && s.begun) {
      s.idleWithdraw = true
      holding += 1
      try {
        await sleepUntil($, s.begun.promise, BEGIN_HOLD_MS, next.signal)
      } finally {
        holding -= 1
      }
      return next(e)
    }
    if (s.halfBeginning) return next(e) // a half holds no prompt
    if (s.state === 'awaiting' && s.pending && s.pending.idle && !s.pending.half) {
      withdrawIdle($, s.pending)
      return next(e)
    }
    const open = s.state === 'awaiting' ? s.pending : undefined
    const begun = s.state === 'beginning' ? s.begun : undefined
    if (!open && !begun) return next(e)
    if (open && (open.unanswered || open.half)) return next(e) // the daemon paused the session over this card: nothing is held on it (RT-2c T27)
    let approved = false
    holding += 1
    try {
      const p = open || (await sleepUntil($, begun.promise, BEGIN_HOLD_MS, next.signal))?.value
      const outcome = p && (await sleepUntil($, p.answer.promise, HOLD_MAX_MS, next.signal))
      // `s.pending === p`: an approval that raced a compaction or a /clear relays nothing
      approved = !!outcome && outcome.value === 'approved' && s.pending === p
    } finally {
      holding -= 1
    }
    return next(approved ? { ...e, context: [...(e.context ?? []), NOTE] } : e)
  }).catch(($, e, next) => {
    log($, 'prompt hold failed (' + (next.error ? next.error.kind : '?') + '); the prompt goes on unchanged')
    return next(e)
  })

  // Compaction (§8.7 (c), deviation 9): an approved relay not yet written
  // skips an AUTO compaction (the handoff is written from the full context);
  // a manual /compact runs, the person asked for it. An open request, any
  // trigger, is reported cancelled{compacted}: the daemon closes its approval
  // row (P5a-2b closeRequestOfReportedOp), every dialog closes and `pdx relay
  // wait` exits 12, which releases the held prompts. No .catch: a hook that
  // throws here lets the compaction run.
  on('session.compact', async ($, e, next) => {
    if (!s.interactive || e.agentId || e.trigger === 'precompute') return next(e)
    disarmIdle()
    // Claude Code's idle compaction runs between turns; a context-full auto compaction runs inside one (spec §4.5). Only
    // told apart once hello advertised the feature (an older daemon does not know `idle`).
    const trigger = e.trigger === 'auto' && !s.turnRunning && s.idleMinutes > 0 ? 'idle' : e.trigger
    // A member's idle compaction (RT-4 T42, Gate M-1): an auto compaction with no main turn running. It is stopped, and the daemon tells
    // the lead to decide (relay, hand over and close, close). A context-full compaction runs inside a turn; a relay under way keeps its rule below.
    // Only when the daemon says it decides these (hello's idle_intercept covers members): an older daemon leaves the compaction as before.
    if (s.helloOK && s.idleIntercept >= 1 && s.role === 'member' && e.trigger === 'auto' && !s.turnRunning && s.state === 'idle') {
      interceptedLater($)
      return { skip: SKIP_MEMBER_IDLE }
    }
    if (s.state === 'approved') {
      if (e.trigger === 'auto') return { skip: SKIP_COMPACT }
      return compactedAfter($, e, await next(e), trigger)
    }
    if (s.state === 'awaiting' && s.pending) {
      const op = s.pending.op.id
      toIdle($) // a held prompt goes on at once, unchanged, before the report
      $.ui.status(undefined)
      report($, op, 'cancelled', ['--error', 'compacted'])
    } else if (s.state === 'beginning') {
      toIdle($) // the begin still out answers for a gone generation: its op is cancelled{abandoned}
    }
    dropHalf($, false) // the daemon deletes the half's row at a compaction (RT-3b T36)
    s.lastAskPct = undefined // after a compaction the next ask needs ≥ threshold again
    s.askEpoch++ // an ask in the air answers for the context that is gone: it must not put its lastAskPct back
    s.askBusy = undefined
    return compactedAfter($, e, await next(e), trigger)
  })

  on('command.run', { command: 'team' }, async ($, e) => teamCommand($, e, false))
  on('command.run', { command: 'lead' }, async ($, e) => teamCommand($, e, true)) // deprecated: the same as /team, plus a line saying so

  // /relay off|on|status (§8.7 (a)): the person waits for the answer, so this
  // one daemon call is awaited in the hook, bounded at SELF_TIMEOUT_MS; a
  // timeout (read as 20), 20 or 21 says the daemon is unreachable.
  on('command.run', { command: 'relay' }, async ($, e) => {
    const action = (e.args || '').trim() || 'now'
    if (action === 'now') return relayNow($)
    if (!['off', 'on', 'status'].includes(action)) return { text: RELAY_USAGE }
    const r = await pdx($, ['relay', 'self', action, '--session', await $.session.id()], SELF_TIMEOUT_MS)
    if (r.exitCode === 20 || r.exitCode === 21) return { text: RELAY_UNREACHABLE }
    // on|off in a member: the daemon's 409 member_relay_is_leads, exit 13 (P5b-3 review)
    if (r.exitCode === 13 && stderrCode(r) === 'member_relay_is_leads') return { text: RELAY_MEMBER }
    if (r.exitCode !== 0) return { text: 'pdx relay self ' + action + ' 失敗：' + (r.stderr || '').trim() }
    const b = parseJSON(r.stdout) || {}
    if (b.member) return { text: RELAY_MEMBER } // status in a member answers 200
    if (action === 'on') s.lastAskPct = undefined // asked again at once (still only after hello answered)
    const host = b.host_switch === false ? '主機開關 關' : '主機開關 開'
    const label = { on: '開啟', off: '關閉', paused: '本 session 暫停' }[b.self_relay] || String(b.self_relay)
    return { text: '自我接力：' + label + '（' + host + '；門檻 ' + s.threshold + '%）' }
  })
}

