// Purdex mod — member relay, the pure half (plan v3 P6-6; spec §8.2 steps 3–8, M1, M28).
//
// A lead asks a member to relay with a control message: a peer message whose text carries
// `[pdx-relay:control] op=<uuid>`. register.js (which owns the shared state and every `$` call)
//   - takes it in `session.receive`, always, busy or idle: the model never sees it;
//   - tells the daemon from a timer that the mod has it (`pdx relay seen`, Q2 branch A);
//   - claims the op only when no main-conversation turn runs: at once when idle, else at that
//     turn's turn.complete (codex finding 1), then takes the write path a self relay takes after
//     an approval: write → check → fix ×2 → written → /clear → seed → done.
//   - a claim that fails does nothing: the daemon's own timeout reports it.
//
// The mod's static rules never follow `$` across an import (Q3 deviation: the receive hook and
// the claim cannot live here), so this file holds what needs no `$`: reading the control message,
// checking a claim's answer, and writing the team facts of the write prompt.

const CONTROL_PREFIX = '[pdx-relay:control] op=' // team.RelayControlPrefix
const UUID = '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}'
const CONTROL_RE = new RegExp(CONTROL_PREFIX.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(' + UUID + ')')

export const CONSUMED = 'pdx relay control message' // the reason logged for a consumed delivery

// The re-ask after a pause (the quota pause, UP-4): `[pdx-relay:control] reask id=<uuid>` (team.PauseReaskControlPrefix).
// A different marker from the op control above, so neither parser can take the other's message.
const REASK_PREFIX = '[pdx-relay:control] reask id='
// The marker stands alone on its own line (the daemon sends the control line and nothing else) and the message is short: a quote, a
// sentence or a tool result that merely mentions it is ordinary text, not a message to consume.
const REASK_RE = new RegExp('(?:^|\\n)' + REASK_PREFIX.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(' + UUID + ')[ \\t]*(?:\\r?\\n|$)')
const REASK_MAX_TEXT = 2048
export const CONSUMED_REASK = 'pdx relay reask control message'

// controlReask is the release token of a reask control message, '' for any other delivery. Only a peer's text counts, as for controlOp.
export function controlReask(e) {
  if (!e || !e.origin || e.origin.kind !== 'peer' || typeof e.text !== 'string' || e.text.length > REASK_MAX_TEXT) return ''
  const m = REASK_RE.exec(e.text)
  return m ? m[1] : ''
}

// controlOp is the op id of a control message, '' for any other delivery. Only a peer's text counts
// (M1): the same words typed by the user, or in a tool result, are ordinary text.
export function controlOp(e) {
  if (!e || !e.origin || e.origin.kind !== 'peer' || typeof e.text !== 'string') return ''
  const m = CONTROL_RE.exec(e.text)
  return m ? m[1] : ''
}

// claimOp is the op of a claim's answer (`pdx relay claim` stdout), undefined when it is not one.
export function claimOp(body) {
  const op = body && body.op
  return op && typeof op.id === 'string' && typeof op.handoff_path === 'string' ? op : undefined
}

// leadLine is a member's `{{team}}` (write prompt tail §8.2 step 4), starting with a newline since the
// placeholder ends the whoami line. `clean` makes third-party text safe (register.js cleanGit).
export function leadLine(lead, clean) {
  return '\n- 我的 lead：' + clean(String(lead.address)) + '（ref ' + clean(String(lead.ref)) + '，team ' + clean(String(lead.team_id)) + '）'
}

// rosterLines is a lead's `{{team}}` from `pdx team --json`'s answer (undefined when it was unreadable).
// Titles and directories are third-party text: cleaned, one line each.
export function rosterLines(view, clean) {
  if (!view || typeof view !== 'object') return '\n- 我管理的 members：（讀不到，接手後請用 pdx team 查）'
  const members = Array.isArray(view.members) ? view.members : []
  if (members.length === 0) return '\n- 我管理的 members：無'
  const one = (v) => clean(String(v ?? '')).replace(/\s+/g, ' ').trim()
  return '\n- 我管理的 members：' + members.map((m) => '\n  - ' + one(m.address) + '（ref ' + one(m.ref) + '，title ' + (one(m.title) || '無') + '，cwd ' + one(m.cwd) + '）').join('')
}

// ---- /team (relay/team rules v2, RT-1c) ----

const MODEL_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}(\[1m\])?$/ // team.ValidModel
const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'] // team.ValidEffort
const TEAM_USAGE = '用法：/team [名稱或說明] | spawn <任務> [--model m] [--effort e] | adopt <ref> | release <ref> | kill <ref>'
export const SPAWN_USAGE = '用法：/team spawn <任務> [--model m] [--effort e]'

const PERSONA_CODE_RE = /^[a-z]{2,16}$/ // the shape `pdx names` keeps (cmd/pdx leadNameCode)

// parseTeamNames reads the stdout of `pdx names --json` (name pool v2 spec §5.3): { leadName: true, personas: [{ code, name }] } when
// the daemon takes a lead name and the list is well formed, otherwise undefined, which is how every failure — an older pdx with no
// such command, a daemon without team.lead_name.v1, an answer that is not what was asked — leaves /team as it was before names.
export function parseTeamNames(stdout) {
  let b
  try { b = JSON.parse(String(stdout ?? '')) } catch { return undefined }
  if (!b || typeof b !== 'object' || b.lead_name !== true || !Array.isArray(b.personas)) return undefined
  const personas = []
  for (const p of b.personas) {
    if (!p || typeof p !== 'object' || typeof p.code !== 'string' || !PERSONA_CODE_RE.test(p.code)) return undefined
    personas.push({ code: p.code, name: typeof p.name === 'string' ? p.name : '' })
  }
  return { leadName: true, personas }
}

// personaMatches are the personas a typed word names: the word is compared, case-insensitively, with each persona's code and with
// the first word of its display name. A persona counts once however it matched.
function personaMatches(word, personas) {
  const w = word.toLowerCase()
  return personas.filter((p) => p.code.toLowerCase() === w || (p.name.trim().split(/\s+/)[0] || '').toLowerCase() === w)
}

// parseTeamArgs reads what follows `/team`: { kind: 'show' } (nothing), { kind: 'lead', note } (any other text),
// { kind: 'spawn', task, model?, effort? }, { kind: 'adopt' | 'release' | 'kill', ref } or { error }. `--model` and
// `--effort` belong to spawn only (their values are the CLI's own lists); a word of another kind is part of the note.
//
// names (parseTeamNames, optional) is the persona list of a daemon that takes a lead name. With it the lead kind learns two
// things: the first word names exactly one persona → { kind: 'lead', note: <the rest>, leadName: <its code> }, a lead at once
// under that name; otherwise (no persona, or more than one: the daemon never picks) → { kind: 'lead', note, card: true }, a
// request that waits on the card where the person picks. Nothing typed is { kind: 'show', card: true }, which a session that
// leads still answers with its roster. Without names it is all exactly as before.
export function parseTeamArgs(args, names) {
  const text = String(args ?? '').trim()
  const named = names && names.leadName === true // a daemon that takes a lead name, with its persona list
  if (text === '') return named ? { kind: 'show', card: true } : { kind: 'show' }
  const words = text.split(/\s+/)
  const head = words[0]
  if (head === 'spawn') {
    const out = { kind: 'spawn', task: '' }
    const task = []
    for (let i = 1; i < words.length; i++) {
      const w = words[i]
      const m = /^--(model|effort)(?:=(.*))?$/.exec(w)
      if (!m) { task.push(w); continue }
      const name = m[1]
      let value = m[2]
      if (value === undefined) value = words[++i]
      if (value === undefined || value === '' || value.startsWith('--')) return { error: '--' + name + ' 需要一個值。' + SPAWN_USAGE }
      if (name === 'model' && !MODEL_RE.test(value)) return { error: '--model 的值不合法：' + value.slice(0, 40) }
      if (name === 'effort' && !EFFORTS.includes(value)) return { error: '--effort 只能是 ' + EFFORTS.join('、') + '：' + value.slice(0, 40) }
      out[name] = value
    }
    out.task = task.join(' ')
    if (out.task === '') return { error: SPAWN_USAGE }
    return out
  }
  if (head === 'adopt' || head === 'release' || head === 'kill') {
    if (words.length !== 2 || words[1].startsWith('-')) return { error: '用法：/team ' + head + ' <ref>' }
    return { kind: head, ref: words[1] }
  }
  if (named) {
    const hit = personaMatches(head, names.personas)
    if (hit.length === 1) return { kind: 'lead', note: text.slice(head.length).trim(), leadName: hit[0].code }
    return { kind: 'lead', note: text, card: true }
  }
  return { kind: 'lead', note: text }
}

export { TEAM_USAGE }

